NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: 'V začetku je bila Beseda in Beseda je bila z Bogom in Beseda je bila Bog.',
        2: 'Ista je bila v začetku z Bogom.',
        3: 'Vse stvari so bile narejene po njem in brez njega ni bilo narejeno nič, kar je bilo narejeno.',
        4: 'V njem je bilo življenje in življenje je bilo svetloba ljudem.',
        5: 'In svetloba sveti v temi, tema pa je ni doumela.',
        6: 'Bil je človek, poslan od Boga, katerega ime je bilo Janez.',
        7: 'Ta isti je prišel za pričo, da pričuje o Svetlobi, da bodo vsi ljudje po njem lahko verovali.',
        8: 'Ni bil on ta Svetloba, ampak je bil poslan, da pričuje o tej Svetlobi.',
        9: '§ To je bila resnična Svetloba, ki razsvetljuje vsakega človeka, ki prihaja na svet.',
        10: 'Bil je na svetu in svet je bil narejen po njem, svet pa ga ni spoznal.',
        11: 'Prišel je k svojim lastnim, njegovi lastni pa ga niso sprejeli.',
        12: 'Toda tolikim, kot so ga sprejeli, njim je on dal moč, da postanejo Božji sinovi, torej njim, ki verujejo v njegovo ime,',
        13: 'ki so bili rojeni, ne iz krvi niti ne iz volje mesa niti ne iz volje moža, temveč iz Boga.',
        14: 'In Beseda je bila narejena meso in prebivala med nami (in zagledali smo njegovo slavo, slavo kot od edinorojenega od Očeta) polno milosti in resnice.',
        15: 'Janez je pričeval o njem in klical, rekoč: »Ta je bil tisti, o katerem sem govoril: ›Kdor prihaja za menoj, je obstajal pred menoj, kajti bil je prej kakor jaz.‹«',
        16: 'In iz njegove polnosti smo vsi prejeli in to milost za milostjo.',
        17: 'Kajti postava je bila dana po Mojzesu, toda milost in resnica sta prišli po Jezusu Kristusu.',
        18: '§ Noben človek nikoli ni videl Boga. Edinorojeni Sin, ki je v Očetovem naročju, on ga je razodel.',
        19: 'In to je Janezovo pričevanje, ko so Judje poslali iz Jeruzalema duhovnike in Lévijevce, da ga vprašajo: »Kdo si ti?«',
        20: '§ In priznal je in ni zanikal, temveč priznal: »Jaz nisem Kristus.«',
        21: 'In vprašali so ga: »Kaj torej? Ali si Elija?« In reče: »Nisem.« »Ali si ti ta prerok?« In odgovoril je: »Ne.«',
        22: 'Potem so mu rekli: »Kdo si? Da bomo lahko dali odgovor tem, ki so nas poslali. Kaj praviš sam o sebi?«',
        23: 'Rekel je: »Jaz sem glas nekoga, ki kliče v divjini: ›Naredite Gospodovo pot ravno,‹ kakor je rekel prerok Izaija.«',
        24: 'Ti pa, ki so bili poslani, so bili izmed farizejev.',
        25: 'In vprašali so ga ter mu rekli: »Zakaj potem krščuješ, če ti nisi ta Kristus niti Elija niti ta prerok?«',
        26: 'Janez jim je odgovoril, rekoč: »Jaz krščujem z vodo, toda tam, med vami, stoji nekdo, ki ga vi ne poznate.',
        27: '§ On je ta, ki prihaja za menoj, in je pred menoj, čigar čevljev jermena nisem vreden odvezati.«',
        28: 'Te stvari so se zgodile v Betaniji, onstran Jordana, kjer je Janez krščeval.',
        29: 'Naslednji dan zagleda Janez k njemu prihajati Jezusa in reče: »Glejte, Jagnje Božje, ki odvzema greh sveta.',
        30: 'To je on, o katerem sem rekel: ›Za menoj prihaja mož, ki je obstajal pred menoj, kajti bil je pred menoj.‹',
        31: 'In nisem ga poznal, vendar sem zato prišel krščevat z vodo, da bi se on razodel Izraelu.«',
        32: 'In Janez je izjavil, rekoč: »Videl sem Duha spuščati se z neba, kakor golobico in je ostal na njem.',
        33: 'In nisem ga poznal, toda kdor me je poslal, da krščujem z vodo, isti mi je rekel: ›Na kogar boš videl spuščati se Duha in ostajati na njem, isti je ta, ki krščuje s Svetim Duhom.‹',
        34: 'In videl sem in izjavil, da je ta Božji Sin.«',
        35: 'Naslednji dan je Janez ponovno stal in dva izmed njegovih učencev',
        36: 'in ko je gledal na Jezusa, medtem ko je hodil, reče: »Glej, Jagnje Božje!«',
        37: 'Dva učenca pa sta ga slišala govoriti in šla za Jezusom.',
        38: 'Potem se je Jezus obrnil in ju videl slediti ter jima reče: »Kaj iščeta?« Rekla sta mu: »Rabi (kar prevedeno pomeni Učitelj), kje prebivaš?«',
        39: 'Reče jima: »Pridita in poglejta.« Prišla sta in videla, kje prebiva ter ta dan ostala z njim, kajti bilo je okrog desete ure.',
        40: '§ Eden izmed dveh, ki sta slišala Janeza govoriti in sta mu sledila, je bil Andrej, brat Simona Petra.',
        41: 'Ta je najprej našel svojega lastnega brata Simona in mu rekel: »Našli smo Mesija,« kar je prevedeno, Kristusa.',
        42: '§ In privedel ga je k Jezusu. In ko ga je Jezus pogledal, je rekel: »Ti si Simon, Jonov sin. Imenoval se boš Kefa,« kar je po razlagi: ›Kamen.‹',
        43: 'Naslednji dan je Jezus nameraval oditi naprej v Galilejo in najde Filipa ter mu reče: »Sledi mi.«',
        44: 'Torej Filip pa je bil iz Betsajde, Andrejevega in Petrovega mesta.',
        45: 'Filip najde Natánaela in mu reče: »Našli smo tistega, o katerem so Mojzes in preroki pisali v postavi, Jezusa iz Nazareta, Jožefovega sina.«',
        46: 'Natánael pa mu je rekel: »Ali lahko iz Nazareta pride kakršnakoli dobra stvar?« Filip mu reče: »Pridi in poglej.«',
        47: 'Jezus je videl k njemu prihajati Natánaela in reče o njem: »Glejte, pravi Izraelec, v katerem ni zvijače!«',
        48: 'Natánael mu reče: »Od kod me poznaš?« Jezus je odgovoril in mu rekel: »Preden te je Filip poklical, sem te videl, ko si bil pod figovim drevesom.«',
        49: 'Natánael je odgovoril in mu reče: »Rabi, ti si Božji Sin. Ti si Izraelov Kralj.«',
        50: 'Jezus je odgovoril in mu rekel: »Ker sem ti rekel: ›Videl sem te pod figovim drevesom,‹ veruješ? Videl boš večje stvari kakor te.«',
        51: 'In reče mu: »Resnično, resnično, povem vam: ›Odslej boste videli odprta nebesa in Božje angele, ki se vzpenjajo in spuščajo nad Sinom človekovim.‹«',
    },
    2: {
        1: 'In tretji dan je bila v galilejski Kani svatba in Jezusova mati je bila tam.',
        2: 'Na svatbo pa so bili povabljeni tako Jezus kakor njegovi učenci.',
        3: 'In ko je zmanjkalo vina, mu Jezusova mati reče: »Vina nimajo.«',
        4: 'Jezus ji reče: »Ženska, kaj imam opraviti s teboj? Moja ura še ni prišla.«',
        5: 'Njegova mati reče služabnikom: »Karkoli vam reče, to storite.«',
        6: 'In tam je bilo postavljenih šest kamnitih posod za vodo, po običaju judovskega očiščevanja, ki so vsebovale vsaka po dva ali tri sodčke.',
        7: 'Jezus jim reče: »Napolnite posode za vodo z vodo.« In napolnili so jih do roba.',
        8: 'In reče jim: »Zajemite torej in nesite k vodju gostije.« In oni so to odnesli.',
        9: 'Ko je vodja gostije pokusil vodo, ki je postala vino in ni vedel, od kod je bila (toda služabniki, ki so zajemali vodo, so vedeli), je vodja gostije poklical ženina',
        10: 'ter mu reče: »Vsak človek na začetku postavi dobro vino, potem pa, ko se ljudje temeljito napijejo, to, ki je slabše. Toda ti si dobro vino prihranil do zdaj.«',
        11: 'Ta začetek čudežev je Jezus storil v galilejski Kani in jasno pokazal svojo slavo in njegovi učenci so verovali vanj.',
        12: 'Po tem je odšel dol v Kafarnáum, on in njegova mati, njegovi bratje ter njegovi učenci in tam so ostali ne mnogo dni.',
        13: 'In blizu je bila judovska pasha in Jezus je odšel gor v Jeruzalem',
        14: 'in našel v templju te, ki so prodajali vole in ovce in golobice in menjalce denarja sedeti.',
        15: 'In ko je iz majhnih vrvi naredil bič, jih je vse izgnal iz templja in ovce in vole in iztresel denar menjalcem ter prevrnil mize',
        16: 'in rekel tem, ki so prodajali golobice: »Odnesite te stvari od tod. Ne delajte hiše mojega Očeta za hišo trgovanja.«',
        17: 'In njegovi učenci so se spomnili, da je bilo pisano: ›Gorečnost za tvojo hišo me je použila.‹',
        18: 'Potem so Judje odgovorili in mu rekli: »Kakšno znamenje nam pokažeš, glede na to, da delaš te stvari?«',
        19: 'Jezus je odgovoril in jim rekel: »Uničite ta tempelj in v treh dneh ga bom postavil pokonci.«',
        20: 'Tedaj so Judje rekli: »Ta tempelj je bil v gradnji šestinštirideset let, ti pa ga hočeš postaviti v treh dneh?«',
        21: 'Toda govoril je o templju svojega telesa.',
        22: 'Ko je bil torej obujen od mrtvih, so se njegovi učenci spomnili, da jim je to rekel in verjeli so pismu ter besedi, ki jo je Jezus rekel.',
        23: 'Torej ko je bil za pasho, na praznični dan, v Jeruzalemu, so mnogi, ko so videli čudeže, ki jih je storil, verovali v njegovo ime.',
        24: 'Toda Jezus se jim ni zaupal, ker je vse ljudi poznal',
        25: 'in ni potreboval, da bi kdorkoli pričeval o človeku, kajti vedel je, kaj je bilo v človeku.',
    },
    3: {
        1: 'Bil je človek izmed farizejev, po imenu Nikodém, vladar Judov.',
        2: 'Ta isti je ponoči prišel k Jezusu in mu rekel: »Rabi, vemo, da si učitelj, ki je prišel od Boga, kajti noben človek ne more delati teh čudežev, ki jih delaš ti, razen če ni Bog z njim.«',
        3: 'Jezus je odgovoril in mu rekel: »Resnično, resnično, povem ti: ›Razen če se človek ponovno ne rodi, ne more videti Božjega kraljestva.‹«',
        4: 'Nikodém mu reče: »Kako je lahko človek ponovno rojen, ko je star? Ali lahko drugič vstopi v maternico svoje matere in se rodi?«',
        5: 'Jezus je odgovoril: »Resnično, resnično, povem ti: ›Razen če se človek ne rodi iz vode in iz Duha, ne more vstopiti v Božje kraljestvo.‹',
        6: 'To, kar je rojeno iz mesa, je meso, in to, kar je rojeno iz Duha, je duh.',
        7: 'Ne čudi se, da sem ti rekel: ›Morate se ponovno roditi.‹',
        8: 'Veter piha, kjer želi in slišiš zvok le-tega, toda ne moreš povedati, od kod prihaja in kam gre. Tako je z vsakim, ki je rojen iz Duha.«',
        9: 'Nikodém je odgovoril in mu rekel: »Kako so te stvari mogoče?«',
        10: 'Jezus je odgovoril in mu rekel: »Ali si ti učitelj Izraelu, pa ne veš teh stvari?',
        11: 'Resnično, resnično, povem ti: ›Mi govorimo to, kar vemo in pričujemo to, kar smo videli, vi pa našega pričevanja ne sprejemate.',
        12: 'Če sem vam govoril zemeljske stvari in niste verovali, kako boste verovali, če vam povem o nebeških stvareh?',
        13: '§ In noben človek se ni dvignil v nebesa, razen tisti, ki je prišel dol iz nebes, celó Sin človekov, ki je v nebesih.',
        14: 'In kakor je Mojzes povzdignil kačo v divjini, točno tako mora biti povzdignjen Sin človekov,',
        15: '§ da se, kdorkoli veruje vanj, ne bo pogubil, temveč bo imel večno življenje.',
        16: '§ Kajti Bog je tako ljubil svet, da je dal svojega edinorojenega Sina, da kdorkoli veruje vanj, se ne bo pogubil, temveč bo imel večno življenje.',
        17: 'Kajti Bog svojega Sina ni poslal na svet, da svet obsodi, temveč, da bi bil svet po njem lahko rešen.',
        18: 'Kdor veruje vanj, ni obsojen, toda kdor ne veruje, je že obsojen, ker ni veroval v ime edinorojenega Božjega Sina.',
        19: 'In to je obsodba, da je svetloba prišla na svet, ljudje pa so raje ljubili temo kakor svetlobo, ker so bila njihova dejanja hudobna.',
        20: 'Kajti vsak, kdor počne zlo, sovraži svetlobo niti ne prihaja k svetlobi, da njegova dejanja ne bi bila pograjana.',
        21: 'Toda kdor ravna po resnici, prihaja k svetlobi, da bi se njegova dejanja lahko razodela, da so narejena v Bogu.‹«',
        22: 'Po teh besedah so prišli Jezus in njegovi učenci v judejsko deželo in z njimi je ostal tam ter krščeval.',
        23: 'Pa tudi Janez je krščeval v Enónu blizu Salíma, ker je bilo tam veliko vode; in prihajali so in bili so krščeni.',
        24: 'Kajti Janez še ni bil vržen v ječo.',
        25: 'Potem je med nekaterimi Janezovimi učenci in Judi nastalo pričkanje glede očiščevanja.',
        26: 'In prišli so k Janezu ter mu rekli: »Rabi, kdor je bil s teboj onstran Jordana, o katerem prinašaš pričevanje, glej, isti krščuje in vsi ljudje prihajajo k njemu.«',
        27: 'Janez je odgovoril in rekel: »Človek ne more ničesar prejeti, razen če mu ni dano iz nebes.',
        28: 'Vi sami mi prinašate pričevanje, da sem rekel: ›Jaz nisem Kristus, temveč, da sem poslan pred njim.‹',
        29: 'Kdor ima nevesto, je ženin, toda ženinov prijatelj, ki stoji in ga posluša, se silno razveseljuje zaradi ženinovega glasu. Ta moja radost je torej dopolnjena.',
        30: 'On mora rasti, toda jaz se moram manjšati.',
        31: 'Kdor prihaja od zgoraj, je nad vsem. Kdor je z zemlje, je zemeljski in govori zemeljsko. Kdor prihaja iz nebes, je nad vsem.',
        32: 'Kar je videl in slišal, to pričuje in noben človek ne sprejema njegovega pričevanja.',
        33: 'Kdor je sprejel njegovo pričevanje, je pristavil k njegovemu pečatu, da je Bog resničen.',
        34: 'Kajti tisti, ki ga je Bog poslal, govori Božje besede, kajti Bog mu ne daje Duha na mero.',
        35: 'Oče ljubi Sina in mu je vse stvari dal v njegovo roko.',
        36: 'Kdor veruje v Sina, ima večno življenje; kdor pa ne veruje Sinu, ne bo videl življenja, temveč na njem ostaja Božji bes.«',
    },
    4: {
        1: '§ Ko je torej Gospod izvedel, kako so farizeji slišali, da je Jezus pridobil in krstil več učencev kakor Janez,',
        2: '(čeprav Jezus sam ni krščeval, temveč njegovi učenci),',
        3: 'je zapustil Judejo in ponovno odšel v Galilejo.',
        4: 'Brezpogojno pa je moral iti skozi Samarijo.',
        5: 'Potem je prišel v samarijsko mesto, ki se imenuje Sihár, blizu kosa zemljišča, ki ga je Jakob dal svojemu sinu Jožefu.',
        6: 'Torej tam [pa] je bil Jakobov vodnjak. Jezus zatorej, opešan od svojega potovanja, tako sede na vodnjak; bilo pa je okoli šeste ure.',
        7: 'Tja prihaja ženska iz Samarije, da zajame vode. Jezus ji reče: »Daj mi piti.«',
        8: '(Kajti njegovi učenci so odšli proč v mesto, da kupijo hrano.)',
        9: 'Potem mu ženska iz Samarije reče: »Kako je to, da ti, ki si Jud, prosiš piti od mene, ki sem ženska iz Samarije? Kajti Judje s Samarijani nimajo nobenega opravka.«',
        10: 'Jezus je odgovoril in ji rekel: »Če bi poznala Božji dar in kdo je, ki ti govori: ›Daj mi, da pijem,‹ bi prosila od njega in dal bi ti žive vode.«',
        11: 'Ženska mu reče: »Gospod, nimaš s čim zajeti, vodnjak pa je globok. Od kod imaš potem to živo vodo?',
        12: 'Ali si ti večji kakor naš oče Jakob, ki nam je dal vodnjak in je od tega pil on sam in njegovi otroci in njegova živina?«',
        13: 'Jezus je odgovoril in ji rekel: »Kdorkoli pije od te vode, bo ponovno žejen,',
        14: 'toda kdorkoli pije od vode, ki mu jo bom jaz dal, ne bo nikoli žejen, temveč bo voda, ki mu jo bom jaz dal, postala v njem izvir vode, ki izvira v večno življenje.«',
        15: 'Ženska mu reče: »Gospod, daj mi te vode, da ne bom žejna niti ne bom hodila sèm zajemat.«',
        16: 'Jezus ji reče: »Pojdi, pokliči svojega soproga in pridi sèm.«',
        17: 'Ženska je odgovorila in rekla: »Nimam soproga.« Jezus ji je rekel: »To si dobro povedala: ›Nimam soproga,‹',
        18: 'kajti imela si pet soprogov in ta, ki ga imaš sedaj, ni tvoj soprog. To si iskreno povedala.«',
        19: 'Ženska mu reče: »Gospod, zaznavam, da si prerok.',
        20: 'Naši očetje so oboževali na tej gori, vi pa pravite, da je v Jeruzalemu kraj, kjer morajo ljudje oboževati.«',
        21: 'Jezus ji reče: »Ženska, veruj mi, prihaja ura, ko ne boste oboževali Očeta ne na tej gori niti ne v Jeruzalemu.',
        22: 'Vi obožujete, česar ne poznate. Mi vemo kaj obožujemo, kajti rešitev duš je od Judov.',
        23: 'Toda prihaja ura in je sedaj, ko bodo pravi oboževalci oboževali Očeta v duhu in resnici, kajti Oče išče takšne, da ga obožujejo.',
        24: 'Bog je Duh, tisti pa, ki ga obožujejo, ga morajo oboževati v duhu in v resnici.«',
        25: 'Ženska mu reče: »Vem, da prihaja Mesija, ki se imenuje Kristus. Ko pride, nam bo povedal vse stvari.«',
        26: 'Jezus ji reče: » Jaz, ki ti govorim, sem ta.«',
        27: 'Zatem pa so prišli njegovi učenci in se čudili, da se je pogovarjal z žensko, vendarle noben človek ni rekel: ›Kaj iščeš?‹ ali: ›Zakaj govoriš z njo?‹',
        28: 'Tedaj je ženska pustila svojo posodo za vodo in odšla svojo pot v mesto ter reče ljudem:',
        29: '»Pridite, poglejte človeka, ki mi je povedal vse stvari, ki sem jih kdaj storila. Ali ni to Kristus?«',
        30: 'Potem so odšli iz mesta in prišli k njemu.',
        31: 'Medtem pa so ga njegovi učenci prosili, rekoč: »Učitelj, jej.«',
        32: 'Vendar jim je rekel: »Jaz imam za jed hrano, ki je vi ne poznate.«',
        33: 'Zato so učenci drug drugemu rekli: »Ali mu je katerikoli človek prinesel kaj za jesti?«',
        34: 'Jezus jim reče: »Moja hrana je, da izvršim voljo tistega, ki me je poslal in da zaključim njegovo delo.',
        35: 'Ali ne pravite: ›Še štiri mesece in potem prihaja žetev?‹ Glejte, povem vam: ›Povzdignite svoje oči in poglejte na polja, kajti že so bela za žetev.‹',
        36: 'In kdor žanje, prejema plače in zbira sad za večno življenje, da se lahko skupaj veselita oba, kdor seje in kdor žanje.',
        37: 'In v tem je ta beseda resnična: ›Eden seje, drugi pa žanje.‹',
        38: 'Pošiljam vas, da požanjete to, za kar niste priložili nobenega truda. Drugi ljudje so se trudili, vi pa ste vstopili v njihove napore.«',
        39: 'In mnogi izmed Samarijanov iz tega mesta so verovali vanj zaradi besed ženske, ki je pričevala: »Povedal mi je vse, kar sem kdaj storila.«',
        40: 'Torej ko so Samarijani prišli k njemu, so ga rotili, da bi ostal z njimi. In ostal je tam dva dni.',
        41: 'In veliko več jih je verovalo zaradi njegove lastne besede.',
        42: 'Ženski pa so rekli: »Sedaj verjamemo, ne zaradi tvojih besed, kajti sami smo ga slišali in vemo, da je ta zares Kristus, Odrešenik sveta.«',
        43: 'Torej po dveh dneh je odšel od tam in šel v Galilejo.',
        44: 'Kajti Jezus je sam izpričal, da prerok v svoji lastni deželi nima spoštovanja.',
        45: 'Potem ko je prišel v Galilejo, so ga Galilejci sprejeli, ker so videli vse stvari, ki jih je na praznik storil v Jeruzalemu, kajti tudi sami so odšli na praznik.',
        46: 'Tako je Jezus ponovno prišel v galilejsko Kano, kjer je vodo spremenil v vino. Tam pa je bil nek visoki plemič, čigar sin je bil bolan v Kafarnáumu.',
        47: 'Ko je slišal, da je Jezus prišel iz Judeje v Galilejo, je odšel k njemu in ga rotil, da bi prišel dol in ozdravil njegovega sina, kajti ta je bil na točki smrti.',
        48: 'Tedaj mu je Jezus rekel: »Razen če ne vidite znamenj in čudežev, ne boste verovali.«',
        49: 'Visoki plemič mu reče: »Gospod, pridi dol, preden moj otrok umre.«',
        50: 'Jezus mu reče: »Pojdi svojo pot, tvoj sin živi.« In mož je verjel besedi, ki mu jo je Jezus govoril in je odšel svojo pot.',
        51: 'Ko je torej šel navzdol, so ga srečali njegovi služabniki in mu povedali, rekoč: »Tvoj sin živi.«',
        52: 'Potem je od njih poizvedel uro, ko je začel okrevati. In oni so mu rekli: »Včeraj ob sedmi uri ga je vročica pustila.«',
        53: 'Tako je oče spoznal, da je bilo to ob isti uri, ob kateri mu je Jezus rekel: »Tvoj sin živi.« In veroval je on sam in njegova celotna hiša.',
        54: 'To je spet drugi čudež, ki ga je Jezus storil, ko je prišel iz Judeje v Galilejo.',
    },
    5: {
        1: 'Po tem je bil judovski praznik in Jezus je odšel gor v Jeruzalem.',
        2: 'Torej v Jeruzalemu je pri ovčjem trgu bazen, ki se v hebrejskem jeziku imenuje Betésda in ima pet preddverij.',
        3: 'V teh leži velika množica nemočnih ljudi, slepih, šepavih in oslabelih, ki čakajo na gibanje vode.',
        4: 'Kajti angel je ob nekem času odšel dol v bazen in vzburkal vodo. Kdorkoli je potem prvi po vzburkanju vode stopil vanj, je bil ozdravljen, katerokoli bolezen je imel.',
        5: 'In tam je bil nek človek, ki je osemintrideset let imel šibkost.',
        6: 'Ko ga je Jezus videl ležati in je vedel, da je bil torej dolgo časa v tem stanju, mu reče: »Hočeš ozdraveti?«',
        7: 'Nemočen človek mu je odgovoril: »Gospod, ko je voda vzburkana, nimam nobenega človeka, da bi me dal v bazen, toda medtem ko prihajam, drug stopi dol pred menoj.«',
        8: 'Jezus mu reče: »Vstani, vzemi svojo posteljo in hôdi.«',
        9: 'In mož je bil takoj ozdravljen in vzel svojo posteljo ter hodil. Na isti dan pa je bil šabat.',
        10: 'Judje so torej rekli temu, ki je bil ozdravljen: »Šabatni dan je. Zate ni zakonito, da nosiš svojo posteljo.«',
        11: 'Odgovoril jim je: »Tisti, ki me je ozdravil, isti mi je rekel: ›Vzemi svojo posteljo in hôdi.‹«',
        12: 'Potem so ga vprašali: »Kateri človek je ta, ki ti je rekel: ›Vzemi svojo posteljo in hôdi?‹«',
        13: 'Tisti pa, ki je bil ozdravljen, ni vedel kdo je bil ta, ker se je Jezus na skrivaj odstranil, [kajti] množica je bila na tem kraju.',
        14: 'Kasneje ga Jezus najde v templju in mu reče: »Glej, ozdravljen si. Ne greši več, da ne bi prišla k tebi hujša stvar.«',
        15: 'Mož je odšel in Judom povedal, da je bil Jezus ta, ki ga je ozdravil.',
        16: '§ In zato so Judje preganjali Jezusa in si prizadevali, da ga ubijejo, ker je te stvari delal na šabatni dan.',
        17: 'Toda Jezus jim je odgovoril: »Moj Oče dela do zdaj in jaz delam.«',
        18: 'Zato so si Judje še bolj prizadevali, da ga ubijejo, ker ni samo prekršil šabata, temveč je tudi rekel, da je bil njegov Oče Bog in se izenačil z Bogom.',
        19: 'Tedaj je Jezus odgovoril in jim rekel: »Resnično, resnično, povem vam: ›Sin ne more ničesar storiti sam od sebe, temveč kar vidi delati Očeta, kajti katerekoli stvari dela on, te prav tako enako dela Sin.',
        20: 'Kajti Oče ima Sina rad in mu kaže vse stvari, ki jih dela sam in pokazal mu bo večja dela kakor ta, da se boste lahko čudili.',
        21: 'Kajti kakor Oče obuja mrtve in jih oživlja, točno tako Sin oživlja kogar hoče.',
        22: 'Kajti Oče ne sodi nobenega človeka, temveč je vso sodbo izročil Sinu,',
        23: 'da bi vsi ljudje spoštovali Sina, tako kakor spoštujejo Očeta. Kdor ne spoštuje Sina, ne spoštuje Očeta, ki ga je poslal.‹',
        24: 'Resnično, resnično, povem vam: ›Kdor sliši mojo besedo in veruje vanj, ki me je poslal, ima večno življenje in ne bo prišel v obsodbo, temveč je iz smrti prešel v življenje.‹',
        25: 'Resnično, resnično, povem vam: ›Prihaja ura in je sedaj, ko bodo mrtvi slišali glas Božjega Sina, in tisti, ki ga zaslišijo, bodo živeli.',
        26: 'Kajti kakor ima Oče življenje v sebi, tako je dal Sinu, da ima življenje v sebi,',
        27: 'in dal mu je tudi oblast, da izvrši sodbo, ker je Sin človekov.‹',
        28: 'Ne čudite se temu, kajti prihaja ura, v kateri bodo vsi, ki so v grobovih, slišali njegov glas',
        29: 'in bodo prišli naprej; tisti, ki so delali dobro, k vstajenju življenja; tisti pa, ki so delali zlo, k vstajenju prekletstva.',
        30: '§ Jaz sam od sebe ne morem ničesar storiti. Kakor slišim, sodim in moja sodba je pravična, ker ne iščem svoje lastne volje, temveč voljo Očeta, ki me je poslal.',
        31: 'Če jaz pričujem o sebi, moje pričevanje ni resnično.',
        32: 'Drug je, ki prinaša pričevanje o meni in vem, da je pričevanje, s katerim pričuje o meni, resnično.',
        33: 'Vi ste poslali k Janezu in on pričuje za resnico.',
        34: 'Toda jaz pričevanja ne sprejemam od človeka, toda te stvari govorim, da bi bili vi lahko rešeni.',
        35: 'On je bil goreča in sijoča svetloba in vi ste se bili voljni nekaj časa veseliti v njegovi svetlobi.',
        36: 'Toda jaz imam večje pričevanje kakor [to] od Janeza, kajti dela, ki mi jih je Oče dal, da jih dokončam, ista dela, ki jih jaz opravljam, pričujejo o meni, da me je poslal Oče.',
        37: 'In sam Oče, ki me je poslal, je prinesel pričevanje o meni. Vi niste nikoli slišali njegovega glasu, niti videli njegovega videza.',
        38: 'In vi nimate njegove besede, ki bi ostajala v vas, kajti kogar je on poslal, njemu ne verujete.',
        39: 'Preiskujete pisma, kajti v njih mislite, [da] imate večno življenje. To pa so ta, ki pričujejo o meni.',
        40: 'In vi nočete priti k meni, da bi lahko imeli življenje.',
        41: 'Ne sprejemam časti od ljudi.',
        42: 'Toda poznam vas, da v sebi nimate Božje ljubezni.',
        43: 'Prišel sem v imenu svojega Očeta in me ne sprejmete. Če bo kdo drug prišel v svojem lastnem imenu, ga boste sprejeli.',
        44: 'Kako lahko verujete vi, ki sprejemate čast drug od drugega, pa ne iščete časti, ki prihaja samo od Boga?',
        45: 'Ne mislite, da vas bom jaz tožil Očetu. Nekdo je, ki vas toži, celó Mojzes, v katerega zaupate.',
        46: 'Kajti če bi verovali Mojzesu, bi verovali meni, kajti pisal je o meni.',
        47: 'Toda če ne verujete njegovim pisanjem, kako boste verovali mojim besedam?«',
    },
    6: {
        1: 'Po teh besedah se je Jezus peljal preko Galilejskega morja, kar je Tiberijsko morje.',
        2: 'Sledila mu je velika množica, ker so videli njegove čudeže, ki jih je storil na teh, ki so bili bolni.',
        3: '§ In Jezus je odšel gor na goro ter tam sédel s svojimi učenci.',
        4: 'In blizu je bila pasha, judovski praznik.',
        5: 'Ko je Jezus tedaj povzdignil svoje oči in zagledal k njemu prihajati veliko skupino, reče Filipu: »Od kod naj kupimo kruha, da bodo ti lahko jedli?«',
        6: 'To pa je rekel, da bi ga preizkusil, kajti sam je vedel, kaj bo storil.',
        7: 'Filip mu je odgovoril: »Dvesto denarjev kruha zanje ni zadosti, da bi vsak izmed njih lahko nekaj vzel.«',
        8: 'Eden izmed njegovih učencev, Andrej, brat Simona Petra, mu reče:',
        9: '»Tukaj je deček, ki ima pet ječmenovih hlebov in dve majhni ribi. Toda kaj je to med tako mnogimi?«',
        10: 'In Jezus je dejal: »Storite, da se ljudje usedejo.« Torej na tem kraju je bilo mnogo trave. Tako so se ljudje usedli, po številu okoli pet tisoč.',
        11: 'In Jezus je vzel hlebe in ko se je zahvalil, je razdelil učencem in učenci tem, ki so se usedli, in podobno od rib, toliko, kolikor so hoteli.',
        12: 'Ko so bili nasičeni, je svojim učencem rekel: »Zberite odlomke, ki ostanejo, da ne bo nič izgubljeno.«',
        13: 'Zato so jih zbrali skupaj in napolnili dvanajst košar z odlomki od petih ječmenovih hlebov, ki so ostali vrh tega tem, ki so jedli.',
        14: 'Tedaj so ti ljudje, ko so videli čudež, ki ga je Jezus storil, rekli: »To je resnično ta prerok, ki naj bi prišel na svet.«',
        15: 'Ko je torej Jezus zaznal, da bodo prišli in ga s silo odvedli, da ga postavijo za kralja, je ponovno sam odšel na goro.',
        16: 'In sedaj, ko je prišel večer, so njegovi učenci odšli dol k morju',
        17: 'in vstopili na ladjo ter se preko morja peljali proti Kafarnáumu. Bilo pa je že temno in Jezus ni prišel k njim.',
        18: 'Zaradi velikega vetra, ki je pihal, se je morje vzdignilo.',
        19: 'Ko so preveslali že okoli petindvajset ali trideset dolžin brazd, so zagledali Jezusa hoditi po morju in prihajati bliže k ladji in bili so prestrašeni.',
        20: 'Toda on jim reče: »Jaz sem, ne bodite prestrašeni.«',
        21: 'Potem so ga voljno sprejeli na ladjo in ladja je bila takoj pri deželi, kamor so šli.',
        22: 'Naslednjega dne, ko je množica, ki je stala na drugi strani morja, videla, da tam ni bilo nobenega drugega čolna, razen tistega, v katerega so vstopili njegovi učenci in da Jezus s svojimi učenci ni vstopil na čoln, temveč, da so njegovi učenci odšli sami',
        23: '(čeprav so iz Tiberije prišli drugi čolni v bližino kraja, kjer so jedli kruh, potem ko se je Gospod zahvalil);',
        24: 'ko je množica torej videla, da Jezusa ni bilo tam niti njegovih učencev, so se tudi sami, ker so iskali Jezusa, vkrcali in prišli v Kafarnáum.',
        25: 'In ko so ga našli na drugi strani morja, so mu rekli: »Rabi, kdaj si prišel sèm?«',
        26: 'Jezus jim je odgovoril in rekel: »Resnično, resnično, povem vam: ›Ne iščete me, ker ste videli čudeže, temveč ker ste jedli od hlebov in bili nasičeni.‹',
        27: 'Ne trudite se za jed, ki propada, temveč za jed, ki vzdrži v večno življenje, ki vam jo bo dal Sin človekov, kajti njega je potrdil Oče Bog.«',
        28: 'Tedaj so mu rekli: »Kaj naj storimo, da bomo lahko delali Božja dela?«',
        29: 'Jezus je odgovoril in jim rekel: »Božje delo je to, da verujete v tistega, ki ga je on poslal.«',
        30: 'Rekli so mu torej: »Kakšno znamenje torej pokažeš, da bomo lahko videli in ti verovali? Kaj delaš?',
        31: 'Naši očetje so v puščavi jedli mano, kakor je pisano: ›Kruh iz nebes jim je dajal jesti.‹«',
        32: 'Potem jim je Jezus rekel: »Resnično, resnično, povem vam: ›Ni vam Mojzes dal tega kruha iz nebes, temveč vam moj Oče daje resničen kruh iz nebes.‹',
        33: 'Kajti Božji kruh je tisti, ki prihaja dol iz nebes in daje svetu življenje.«',
        34: 'Tedaj so mu rekli: »Gospod, vselej nam daj tega kruha.«',
        35: 'In Jezus jim je rekel: »Jaz sem kruh življenja. Kdor prihaja k meni, ne bo nikoli lačen. In kdor vame veruje, ne bo nikoli žejen.',
        36: 'Toda rekel sem vam: ›Da ste me vi tudi videli, pa ne verujete.‹',
        37: 'Vse, kar mi daje Oče, bo prišlo k meni, in tistega, ki prihaja k meni, nikakor ne bom izgnal ven.',
        38: 'Kajti prišel sem dol iz nebes, ne da delam svojo lastno voljo, temveč voljo tistega, ki me je poslal.',
        39: 'In to je volja Očeta, ki me je poslal, da od vsega, kar mi je dal, ne bi ničesar izgubil, temveč bi ob poslednjem dnevu to ponovno dvignil.',
        40: 'In to je volja tistega, ki me je poslal, da bo vsakdo, ki vidi Sina in veruje vanj, lahko imel večno življenje in jaz ga bom dvignil na poslednji dan.«',
        41: 'Judje so tedaj godrnjali nad njim, ker je rekel: »Jaz sem kruh, ki je prišel dol iz nebes.«',
        42: 'In govorili so: »Ali ni to Jezus, Jožefov sin, katerega očeta in mater poznamo? Kako to potem, da pravi: ›Prišel sem dol iz nebes?‹«',
        43: 'Jezus je torej odgovoril in jim rekel: »Ne godrnjajte med seboj.',
        44: 'Nihče ne more priti k meni, razen če ga ne pritegne Oče, ki me je poslal in jaz ga bom dvignil na poslednji dan.',
        45: 'V prerokih je pisano: ›In vsi bodo poučeni od Boga.‹ Vsak torej, ki je slišal in se naučil od Očeta, prihaja k meni.',
        46: 'Ne da je katerikoli človek videl Očeta, samo tisti, ki je od Boga, on je videl Očeta.',
        47: '§ Resnično, resnično, povem vam: ›Kdor veruje vame, ima večno življenje.‹',
        48: 'Jaz sem ta kruh življenja.',
        49: 'Vaši očetje so v divjini jedli mano in so mrtvi.',
        50: 'To je kruh, ki prihaja dol iz nebes, da lahko človek od tega jé in ne umre.',
        51: 'Jaz sem živi kruh, ki je prišel dol iz nebes. Če katerikoli človek od tega kruha jé, bo živel večno, in kruh, ki ga bom jaz dal, je moje meso, ki ga bom dal za življenje sveta.«',
        52: 'Judje so se torej med seboj prepirali, rekoč: »Kako nam lahko ta človek da jesti svoje meso?«',
        53: 'Tedaj jim je Jezus rekel: »Resnično, resnično, povem vam: ›Razen, če ne jeste mesa Sina človekovega in ne pijete njegove krvi, v sebi nimate življenja.',
        54: 'Kdorkoli jé moje meso in pije mojo kri, ima večno življenje in jaz ga bom dvignil na poslednji dan.‹',
        55: 'Kajti zares je moje meso hrana in zares je moja kri pijača.',
        56: 'Kdor jé moje meso in pije mojo kri, prebiva v meni in jaz v njem.',
        57: 'Kakor me je poslal živi Oče in jaz živim po Očetu. Ravno tako, kdor mene jé, celó ta bo živel po meni.',
        58: '§ To je ta kruh, ki je prišel dol iz nebes. Ne kakor vaši očetje, ki so jedli mano in so mrtvi. Kdor jé od tega kruha, bo živel večno.«',
        59: 'Te stvari je povedal v sinagogi, ko je učil v Kafarnáumu.',
        60: 'Zatorej so mnogi izmed njegovih učencev, ko so to slišali, rekli: »To je trda beseda, kdo jo lahko posluša?«',
        61: 'Potem ko je Jezus v sebi vedel, da so njegovi učenci nad tem godrnjali, jim je rekel: »Ali vas to pohujšuje?',
        62: 'Kaj pa, če boste videli Sina človekovega dvigniti se gor, kjer je bil prej?',
        63: 'Duh je, ki oživlja, meso nič ne koristi. Besede, ki vam jih govorim, te so duh in te so življenje.',
        64: 'Toda tam so nekateri izmed vas, ki ne verujejo.« Kajti Jezus je že od začetka vedel kdo so bili ti, ki niso verovali in kdo naj bi ga izdal.',
        65: 'In rekel je: »Zato sem vam rekel, da nihče ne more priti k meni, razen če mu ni dano od mojega Očeta.«',
        66: 'Od tega časa je mnogo izmed njegovih učencev odšlo nazaj in niso več hodili z njim.',
        67: 'Tedaj je Jezus dvanajsterim rekel: »Ali hočete tudi vi oditi?«',
        68: 'Potem mu je Simon Peter odgovoril: »Gospod, h komu naj gremo? Ti imaš besede večnega življenja.',
        69: '§ In mi verujemo in smo prepričani, da si ti ta Kristus, Sin živega Boga.«',
        70: 'Jezus jim je odgovoril: »Ali vas nisem izbral dvanajst in je eden izmed vas hudič?«',
        71: 'Govoril je o Judu Iškarijotu, Simonovem sinu, kajti on je bil ta, ki naj bi ga izdal in je izmed dvanajsterice.',
    },
    7: {
        1: 'Po teh besedah je Jezus hodil po Galileji, kajti ni želel hoditi po Judeji, ker so si Judje prizadevali, da ga ubijejo.',
        2: 'Torej blizu je bil judovski šotorski praznik.',
        3: 'Njegovi bratje so mu zatorej rekli: »Odidi od tod in pojdi v Judejo, da bodo tudi tvoji učenci lahko videli dela, ki jih delaš.',
        4: 'Kajti nobenega človeka ni, ki karkoli dela na skrivnem in si sam prizadeva, da bi bil javno znan. Če delaš te stvari, se pokaži svetu.«',
        5: 'Kajti niti njegovi bratje niso verovali vanj.',
        6: 'Tedaj jim je Jezus rekel: »Moj čas še ni prišel, toda vaš čas je vedno pripravljen.',
        7: 'Vas svet ne more sovražiti, toda mene sovraži, ker pričujem o njem, da so le-tega dela hudobna.',
        8: '§ Pojdite gor na ta praznik. Jaz še ne grem na ta praznik, kajti moj čas še ni dopolnjen.«',
        9: 'Ko jim je povedal te besede, je še vedno prebival v Galileji.',
        10: 'Toda ko so njegovi bratje odšli gor, potem je tudi on odšel gor na praznik, ne javno, temveč kakor bi bilo na skrivnem.',
        11: 'Potem so ga Judje med praznikom iskali in govorili: »Kje je tisti?«',
        12: 'In glede njega je bilo med množico mnogo mrmranja, kajti nekateri so rekli: »Dober človek je,« drugi so rekli: »Ne, temveč zavaja množico.«',
        13: 'Vendar zaradi strahu pred Judi noben človek o njem ni govoril javno.',
        14: 'Torej okoli srede praznika je Jezus odšel gor v tempelj in učil.',
        15: 'In Judje so se čudili, rekoč: »Kako ta človek pozna pisma, saj se jih nikoli ni učil?«',
        16: 'Jezus jim je odgovoril in rekel: »Moj nauk ni moj, temveč tistega, ki me je poslal.',
        17: 'Če hoče katerikoli človek storiti njegovo voljo, bo iz nauka spoznal, če je to od Boga ali če govorim sam od sebe.',
        18: 'Kdor govori o sebi, išče svojo lastno slavo, toda kdor išče slavo tistega, ki ga je poslal, isti je resničen in v njem ni nobene nepravičnosti.',
        19: 'Ali vam ni Mojzes dal postave in še izmed vas se nihče ne drži postave? Zakaj me poskušate ubiti?«',
        20: 'Množica je odgovorila in rekla: »Hudiča imaš. Kdo se pripravlja, da te ubije?«',
        21: 'Jezus je odgovoril in jim rekel: »Eno delo sem storil in vsi se čudite.',
        22: 'Mojzes vam je torej dal obrezovanje (ne, ker je od Mojzesa, temveč od očetov) in vi na šabatni dan obrežete človeka.',
        23: 'Če človek na šabat prejme obrezovanje, da se Mojzesova postava ne bi prekršila; ali ste jezni name, ker sem na šabatni dan ozdravil vsak najmanjši delček človeka?',
        24: 'Ne sodite glede na videz, temveč sodite pravično sodbo.«',
        25: 'Tedaj so nekateri izmed teh iz Jeruzalema rekli: »Ali ni to ta, ki si ga prizadevajo ubiti?',
        26: 'Ampak glejte, pogumno govori, pa mu ničesar ne rečejo. Ali so vladarji zares spoznali, da je ta pravi Kristus?',
        27: 'Vendar mi vemo, od kod je ta človek; toda ko pride Kristus, noben človek ne bo vedel, od kod je.«',
        28: 'Tedaj je Jezus, med poučevanjem v templju, zaklical, rekoč: »Vi me tako poznate, kakor veste od kod sem in nisem prišel sam od sebe, temveč je tisti, ki me je poslal, resničen, ki ga vi ne poznate.',
        29: 'Toda jaz ga poznam, ker sem od njega in me je on poslal.«',
        30: 'Prizadevali so si torej, da ga primejo, toda noben človek nanj ni položil rok, ker njegova ura še ni prišla.',
        31: 'Mnogi izmed množice pa so verovali vanj in rekli: »Ko pride Kristus ali bo storil več čudežev, kakor jih je storil ta človek?«',
        32: 'Farizeji so slišali, da množica glede njega godrnja takšne besede, in farizeji in visoki duhovniki so poslali častnike, da ga primejo.',
        33: 'Potem jim je Jezus rekel: »Še malo časa sem z vami in potem grem k tistemu, ki me je poslal.',
        34: 'Iskali me boste, pa me ne boste našli; in kjer sem jaz, tja vi ne morete priti.«',
        35: '§ Tedaj so Judje med seboj govorili: »Kam bo šel, da ga ne bomo našli? Ali bo šel k razkropljenim med pogane in učil pogane?',
        36: 'Kakšne vrste govorjenje je to, da je rekel: ›Iskali me boste, pa me ne boste našli; in kjer sem jaz, tja vi ne morete priti?‹«',
        37: 'Na zadnji dan, veliki dan praznika, je Jezus vstal in zaklical, rekoč: »Če je katerikoli človek žejen, naj pride k meni in pije.',
        38: 'Kdor veruje vame, kakor pravi pismo, bodo iz njegovega trebuha tekle reke žive vode.«',
        39: '(Toda to je govoril o Duhu, ki naj bi ga prejeli tisti, ki verujejo vanj, kajti Sveti Duh še ni bil dan, zato ker Jezus še ni bil proslavljen.)',
        40: 'Mnogi izmed množice so torej, ko so slišali te besede, rekli: »Resnično, ta je Prerok.«',
        41: 'Drugi so rekli: »Ta je Kristus.« Toda nekateri so rekli: »Mar bo Kristus prišel iz Galileje?',
        42: 'Mar ni pismo reklo: ›Da prihaja Kristus iz Davidovega semena in iz mesta Betlehem, kjer je bil David?‹«',
        43: 'Med množico je bilo torej zaradi njega nesoglasje.',
        44: 'In nekateri izmed njih so ga hoteli prijeti, toda nanj noben človek ni položil rok.',
        45: 'Potem so prišli častniki k visokim duhovnikom in farizejem in ti so jim rekli: »Zakaj ga niste privedli?«',
        46: 'Častniki so odgovorili: »Nikoli [noben] človek ni govoril kakor ta človek.«',
        47: 'Tedaj so jim farizeji odgovorili: »Ali ste tudi vi zavedeni?',
        48: 'Ali je kdo izmed vladarjev ali izmed farizejev veroval vanj?',
        49: 'Toda ta množica, ki ne pozna postave, je prekleta.«',
        50: 'Nikodém (tisti, ki je ponoči prišel k Jezusu in je bil eden izmed njih) jim reče:',
        51: '»Ali naša postava kateregakoli človeka obsodi, preden ga ne zasliši in ne izve, kaj on dela?«',
        52: 'Odgovorili so in mu rekli: »Ali si tudi ti iz Galileje? Preišči in poglej, kajti iz Galileje ne vstane noben prerok.«',
        53: 'In vsak je odšel v svojo lastno hišo.',
    },
    8: {
        1: 'Jezus je odšel k Oljski gori.',
        2: 'Zgodaj zjutraj je ponovno prišel v tempelj in vsi ljudje so prišli k njemu, in usedel se je ter jih učil.',
        3: 'In pisarji in farizeji so k njemu privedli žensko, zasačeno v zakonolomstvu; in ko so jo postavili v sredo,',
        4: '§ so mu rekli: »Učitelj, ta ženska je bila zasačena v zakonolomstvu, pri samem dejanju.',
        5: 'Torej Mojzes nam je v postavi ukazal, da naj bi bili taki kamnani. Toda kaj praviš ti?«',
        6: 'To so rekli, ker so ga skušali, da bi ga lahko obtožili. Jezus pa se je sklonil in s svojim prstom pisal po tleh, kakor da jih ni slišal.',
        7: 'Torej, ko so ga še naprej spraševali, se je vzravnal in jim rekel: »Kdor je med vami brez greha, naj prvi vrže kamen vanjo.«',
        8: 'In ponovno se je sklonil ter pisal po tleh.',
        9: '§ In ti, ki so to slišali, so obsojeni po svoji lastni vesti, drug za drugim odšli ven, s pričetkom pri najstarejših, celó do zadnjega; in Jezus je ostal sam ter ženska, stoječa v sredi.',
        10: 'Ko se je Jezus dvignil in ni videl nikogar razen ženske, ji je rekel: »Ženska, kje so ti tvoji tožniki? Ali te nihče ni obsodil?«',
        11: 'Rekla je: »Noben človek, Gospod.« In Jezus ji je rekel: »Niti te jaz ne obsojam. Pojdi in ne greši več.«',
        12: 'Potem jim je Jezus ponovno spregovoril, rekoč: »Jaz sem svetloba sveta. Kdor sledi meni, ne bo hodil v temi, temveč bo imel svetlobo življenja.«',
        13: 'Farizeji so mu torej rekli: »Ti prinašaš pričevanje o sebi; tvoje pričevanje ni resnično.«',
        14: 'Jezus je odgovoril in jim rekel: »Četudi pričujem o samem sebi, je vendarle moje pričevanje resnično, kajti jaz vem, od kod sem prišel in kam grem, toda vi ne morete povedati, od kod sem prišel in kam grem.',
        15: 'Vi sodite po mesu; jaz ne sodim nobenega človeka.',
        16: 'Če pa vendarle sodim, je moja sodba resnična, kajti nisem sam, temveč jaz in Oče, ki me je poslal.',
        17: 'Tudi v vaši postavi je zapisano, da je pričevanje dveh ljudi resnično.',
        18: 'Jaz sem nekdo, ki pričuje o samem sebi in Oče, ki me je poslal, prinaša pričevanje o meni.«',
        19: 'Tedaj so mu rekli: »Kje je tvoj Oče?« Jezus je odgovoril: »Vi ne poznate niti mene niti mojega Očeta. Če bi poznali mene, bi poznali tudi mojega Očeta.«',
        20: 'Te besede je Jezus govoril v zakladnici, medtem ko je učil v templju. In nanj noben človek ni položil rok, kajti njegova ura še ni prišla.',
        21: 'Potem jim je Jezus ponovno rekel: »Jaz grem svojo pot in iskali me boste in umrli boste v svojih grehih. Kamor grem jaz, vi ne morete priti.«',
        22: 'Tedaj so Judje rekli: »Ali bo samega sebe ubil, ker pravi: ›Kamor grem jaz, vi ne morete priti.‹«',
        23: 'In rekel jim je: »Vi ste od spodaj, jaz sem od zgoraj; vi ste od tega sveta, jaz nisem od tega sveta.',
        24: 'Povedal sem vam torej, da boste umrli v svojih grehih; kajti če ne verujete, da jaz sem, boste umrli v svojih grehih.«',
        25: 'Tedaj so mu rekli: »Kdo si?« In Jezus jim reče: »Celo isti, kakor sem vam povedal od začetka.',
        26: 'Povedati vam imam mnogo besed in soditi o vas, toda tisti, ki me je poslal, je resničen in svetu govorim te besede, ki sem jih slišal od njega.«',
        27: 'Niso pa razumeli, da jim je govoril o Očetu.',
        28: 'Tedaj jim je Jezus rekel: »Ko boste povzdignili Sina človekovega, potem boste spoznali, da jaz sem in da ničesar ne delam sam od sebe, temveč te stvari govorim, kakor me je naučil moj Oče.',
        29: 'In tisti, ki me je poslal, je z menoj. Oče me ni pustil samega, kajti vedno delam te stvari, ki mu ugajajo.«',
        30: 'Ko je govoril te besede, so mnogi verovali vanj.',
        31: 'Tem Judom, ki so verovali vanj, je tedaj Jezus rekel: »Če ostanete v moji besedi, potem ste zares moji učenci',
        32: 'in spoznali boste resnico in resnica vas bo osvobodila.«',
        33: 'Odgovorili so mu: »Mi smo Abrahamovo seme in nikoli nismo bili nobenemu človeku v suženjstvu. Kako praviš: ›Osvobojeni boste?‹«',
        34: 'Jezus jim je odgovoril: »Resnično, resnično, povem vam: ›Kdorkoli zagreši greh, je služabnik greha.',
        35: 'In služabnik v hiši ne ostaja za vedno, toda Sin ostaja večno.',
        36: 'Če vas bo torej Sin osvobodil, boste zares svobodni.',
        37: 'Vem, da ste Abrahamovo seme, toda vi si prizadevate, da me ubijete, ker moja beseda v vas nima prostora.',
        38: 'Jaz govorim to, kar sem videl pri svojem Očetu, vi pa delate to, kar ste videli pri svojem očetu.‹«',
        39: 'Odgovorili so in mu rekli: »Naš oče je Abraham.« Jezus jim reče: »Če bi bili Abrahamovi otroci, bi delali Abrahamova dela.',
        40: 'Toda sedaj si prizadevate, da me ubijete, človeka, ki vam je povedal resnico, ki sem jo slišal od Boga. Tega Abraham ni storil.',
        41: 'Vi opravljate dela svojega očeta.« Tedaj so mu rekli: »Mi nismo rojeni iz prešuštva; mi imamo enega Očeta, celó Boga.«',
        42: 'Jezus jim je rekel: »Če bi bil vaš Oče Bog, bi me ljubili, kajti jaz sem izšel in sem prišel od Boga; niti nisem prišel sam od sebe, temveč me je on poslal.',
        43: 'Zakaj ne razumete mojega govora? Zato ker celó ne morete poslušati moje besede.',
        44: 'Vi ste od svojega očeta, hudiča in počeli boste poželjivosti svojega očeta. On je bil od začetka morilec in ni ostal v resnici, ker v njem ni resnice. Ko govori laž, govori iz svojega lastnega, kajti on je lažnivec in oče le-te.',
        45: 'In ker vam govorim resnico, mi ne verjamete.',
        46: 'Kdo izmed vas me prepričuje o grehu? Če pa govorim resnico, zakaj mi ne verjamete?',
        47: 'Kdor je iz Boga, posluša Božje besede. Vi jih torej ne poslušate, ker niste iz Boga.«',
        48: 'Tedaj so Judje odgovorili in mu rekli: »Ali ne govorimo prav, da si Samarijan in imaš hudiča?«',
        49: 'Jezus je odgovoril: »Jaz nimam hudiča, temveč častim svojega Očeta, vi pa me onečaščate.',
        50: 'In ne iščem svoje lastne slave; obstaja nekdo, ki išče in sodi.',
        51: 'Resnično, resnično, povem vam: ›Če se človek drži moje besede, nikoli ne bo videl smrti.‹«',
        52: 'Tedaj so mu Judje rekli: »Torej, mi vemo, da imaš hudiča. Abraham je mrtev in preroki; ti pa praviš: ›Če se človek drži moje besede, nikoli ne bo okusil smrti.‹',
        53: 'Ali si ti večji kakor naš oče Abraham, ki je mrtev? In tudi preroki so mrtvi. Koga se ti sam delaš?«',
        54: 'Jezus je odgovoril: »Če jaz častim samega sebe, moja čast ni nič. Moj Oče je ta, ki me časti, o katerem vi pravite, da je on vaš Bog.',
        55: 'Vendarle ga vi niste spoznali, toda jaz ga poznam. In če bi rekel: ›Ne poznam ga,‹ bi bil lažnivec, podoben vam. Toda jaz ga poznam in se držim njegove besede.',
        56: 'Vaš oče Abraham se je razveselil, da vidi moj dan. In videl ga je in je bil vesel.«',
        57: 'Tedaj so mu Judje rekli: »Še petdeset let nisi star in si videl Abrahama?«',
        58: 'Jezus jim je rekel: »Resnično, resnično, povem vam: ›Preden je bil Abraham, jaz sem.‹«',
        59: '§ Tedaj so pobrali kamne, da bi jih vrgli vanj, toda Jezus se je skril in odšel iz templja, gredoč skozi njihovo sredo in tako odšel mimo.',
    },
    9: {
        1: 'In ko je Jezus šel mimo, je zagledal človeka, ki je bil slep od svojega rojstva.',
        2: 'In njegovi učenci so ga vprašali, rekoč: »Učitelj, kdo je storil greh, ta človek ali njegovi starši, da je bil rojen slep.«',
        3: 'Jezus je odgovoril: »Niti ni ta človek grešil niti njegovi starši, temveč, da bi se na njem razodela Božja dela.',
        4: 'Dokler je dan, moram delati dela tistega, ki me je poslal. Prihaja noč, ko noben človek ne more delati.',
        5: 'Kolikor dolgo sem na svetu, sem svetloba sveta.«',
        6: 'Ko je to izgovoril, je pljunil na tla in iz sline naredil blato in z blatom mazilil oči slepega človeka',
        7: 'ter mu rekel: »Pojdi, umij se v bazenu Síloi,« (kar je po razlagi: ›Poslani.‹) Odšel je torej svojo pot in se umil in prišel ter videl.',
        8: 'Torej sosedje in tisti, ki so ga prej videli, da je bil slep, so rekli: »Ali ni to tisti, ki je sedel in beračil?«',
        9: 'Nekateri so rekli: »To je on,« drugi so rekli: »Podoben mu je.« Toda on je rekel: »Jaz sem.«',
        10: 'Zaradi tega so mu rekli: »Kako so bile tvoje oči odprte?«',
        11: 'Odgovoril je in rekel: »Človek, ki se imenuje Jezus, je naredil blato ter mazilil moje oči in mi rekel: ›Pojdi k bazenu Síloa in umij.‹ In odšel sem in umil ter prejel vid.«',
        12: 'Potem so mu rekli: »Kje je tisti?« Rekel je: »Ne vem.«',
        13: 'K farizejem so privedli tistega, ki je bil poprej slep.',
        14: 'In bil je šabatni dan, ko je Jezus naredil blato in odprl njegove oči.',
        15: 'Tedaj so ga tudi farizeji ponovno vprašali, kako je prejel svoj vid. Rekel jim je: »Na moje oči je položil blato in sem umil ter vidim.«',
        16: 'Zato so nekateri izmed farizejev rekli: »Ta človek ni od Boga, ker se ne drži šabatnega dne.« Drugi so rekli: »Kako lahko človek, ki je grešnik, dela takšne čudeže?« In med njimi je bilo nesoglasje.',
        17: 'Slepemu možu so ponovno rekli: »Kaj praviš o tistem, ki ti je odprl tvoje oči?« Rekel je: »Prerok je.«',
        18: 'Toda Judje glede njega niso verjeli, da je bil slep in je prejel svoj vid, dokler niso poklicali staršev tega, ki je prejel svoj vid.',
        19: 'In vprašali so ju, rekoč: »Je to vajin sin, o katerem pravite, da je bil rojen slep? Kako potem sedaj vidi?«',
        20: 'Njegova starša sta jim odgovorila in rekla: »Midva veva, da je to najin sin in da je bil rojen slep,',
        21: 'toda na kakšen način on sedaj vidi, midva ne veva; ali kdo je odprl njegove oči, midva ne veva. Dovolj je star, njega vprašajte, on bo govoril zase.«',
        22: 'Te besede so njegovi starši govorili zato, ker so se bali Judov, kajti Judje so se že sporazumeli, da če bi katerikoli človek priznal, da je bil on Kristus, bi bil le-ta izločen iz sinagoge.',
        23: 'Zaradi tega so njegovi starši rekli: »Dovolj je star, njega vprašajte.«',
        24: 'Tedaj so ponovno poklicali moža, ki je bil slep in mu rekli: »Daj Bogu hvalo. Mi vemo, da je ta človek grešnik.«',
        25: 'Odgovoril je in rekel: »Če je grešnik ali ne, ne vem. Eno stvar vem, glede na to, da sem bil slep, sedaj vidim.«',
        26: 'Tedaj so mu ponovno rekli: »Kaj ti je storil? Kako je odprl tvoje oči?«',
        27: 'Odgovoril jim je: »Povedal sem vam že, pa niste poslušali. Zakaj bi to radi ponovno slišali? Hočete biti tudi vi njegovi učenci?«',
        28: 'Tedaj so ga zasramovali in rekli: »Ti si njegov učenec, toda mi smo Mojzesovi učenci.',
        29: 'Mi vemo, da je Mojzesu govoril Bog; glede tega pa ne vemo, od kod je.«',
        30: 'Človek je odgovoril in jim rekel: »Zakaj v tem je čudovita stvar, da vi ne veste, od kod je, pa je vendar odprl moje oči.',
        31: 'Torej vemo, da Bog ne sliši grešnikov; toda če je katerikoli človek oboževalec Boga in izvršuje njegovo voljo, njega on sliši.',
        32: 'Odkar je svet nastal, se ni slišalo, da bi katerikoli človek odprl oči nekoga, ki je bil rojen slep.',
        33: 'Če ta človek ne bi bil od Boga, ne bi mogel ničesar storiti.«',
        34: 'Odgovorili so mu in mu rekli: »Povsem si bil rojen v grehih in nas ti učiš?« In vrgli so ga ven.',
        35: 'Jezus je slišal, da so ga vrgli ven. In ko ga je našel, mu je rekel: »Ali veruješ v Božjega Sina?«',
        36: 'Odgovoril je in rekel: »Kdo je ta, Gospod, da bi lahko veroval vanj?«',
        37: 'Jezus mu je rekel: »Ti si ga oboje [in] videl in ta je, ki govori s teboj.«',
        38: 'In rekel je: »Gospod, verujem.« In ga je oboževal.',
        39: 'Jezus je rekel: »Za sodbo sem prišel na ta svet, da bi tisti, ki ne vidijo, lahko videli in da bi tisti, ki vidijo, lahko oslepeli.«',
        40: 'Nekateri izmed farizejev, ki so bili z njim, so slišali te besede in mu rekli: »Ali smo tudi mi slepi?«',
        41: 'Jezus jim je rekel: »Če bi bili slepi, ne bi imeli greha, toda sedaj pravite: ›Vidimo,‹ zato vaš greh ostaja.«',
    },
    10: {
        1: '»Resnično, resnično, povem vam: ›Kdor v ovčjo stajo ne vstopa pri vratih, temveč se vzpenja po neki drugi poti, ta isti je tat in razbojnik.',
        2: 'Toda kdor vstopa pri vratih, je pastir ovc.',
        3: 'Njemu vratar odpira in ovce slišijo njegov glas in svoje lastne ovce kliče po imenu in jih vodi ven.',
        4: 'In ko svoje lastne ovce poganja naprej, gre pred njimi in ovce mu sledijo, kajti njegov glas poznajo.',
        5: 'Tujcu pa ne bodo sledile, temveč bodo bežale pred njim, kajti glasu tujcev ne poznajo.‹«',
        6: 'Jezus jim je povedal to prispodobo, toda niso razumeli, kaj bi bile te besede, ki jim jih je govoril.',
        7: 'Potem jim je Jezus ponovno rekel: »Resnično, resnično, povem vam: ›Jaz sem vrata ovcam.',
        8: 'Vsi, ki so kadarkoli prišli pred menoj, so tatovi in razbojniki, toda ovce jih niso poslušale.',
        9: 'Jaz sem vrata; če kdorkoli vstopi noter po meni, bo rešen in bo hodil ven in noter ter najde pašo.',
        10: 'Tat ne prihaja, razen da krade in da ubija ter da uničuje. Jaz sem prišel, da bi lahko imeli življenje in da bi ga lahko imeli bolj obilno.',
        11: 'Jaz sem dobri pastir. Dobri pastir daje svoje življenje za ovce.',
        12: 'Toda kdor je najemnik in ni pastir, katerega ovce niso njegova last, vidi prihajati volka in zapusti ovce ter zbeži, volk pa ovce lovi in jih razkropi.',
        13: 'Najemnik beži, ker je najemnik in ne skrbi za ovce.',
        14: 'Jaz sem dobri pastir in poznam svoje ovce in moje poznajo mene.',
        15: 'Kakor Oče pozna mene, točno tako jaz poznam Očeta in svoje življenje dam za ovce.',
        16: 'Imam pa tudi druge ovce, ki niso iz te staje. Tudi te moram privesti in bodo slišale moj glas in bo ena staja in en pastir.',
        17: 'Zato me moj Oče ljubi, ker dam svoje življenje, da ga lahko ponovno prejmem.',
        18: 'Nihče ga ne jemlje od mene, temveč ga dajem sam od sebe. Imam moč, da ga dam in imam moč, da ga ponovno prejmem. To zapoved sem prejel od svojega Očeta.‹«',
        19: 'Zaradi teh besed je bilo med Judi ponovno nesoglasje.',
        20: 'In mnogi izmed njih so rekli: »Hudiča ima, pa tudi nor je; zakaj ga poslušate?«',
        21: 'Drugi so rekli: »To niso besede tistega, ki ima hudiča. Ali lahko hudič slepemu odpre oči?«',
        22: 'V Jeruzalemu pa je bil praznik posvetitve in bila je zima.',
        23: 'In Jezus je hodil v templju po Salomonovem preddverju.',
        24: 'Potem so prišli Judje, ga obkrožili in mu rekli: »Doklej nas boš še pustil, da dvomimo? Če si ti Kristus, nam odkrito povej.«',
        25: 'Jezus jim je odgovoril: »Povedal sem vam, pa niste verovali. Dela, ki jih delam v imenu svojega Očeta, ta pričujejo o meni.',
        26: 'Toda vi ne verujete, ker kakor sem vam povedal, niste izmed mojih ovc.',
        27: 'Moje ovce slišijo moj glas in jaz jih poznam in one mi sledijo,',
        28: 'in dam jim večno življenje in nikoli ne bodo propadle niti jih noben človek ne bo iztrgal iz moje roke.',
        29: 'Moj Oče, ki jih je dal meni, je večji od vseh in noben človek jih ne more izpuliti iz roke mojega Očeta.',
        30: 'Jaz in moj Oče sva eno.«',
        31: 'Po tem so Judje ponovno pobrali kamne, da ga kamnajo.',
        32: 'Jezus jim je odgovoril: »Mnogo dobrih del sem vam pokazal od svojega Očeta; za katerega izmed teh del me kamnate?«',
        33: 'Judje so mu odgovorili, rekoč: »Ne kamnamo te zaradi dobrega dela; temveč zaradi bogokletja; in zato, ker se ti, ki si človek, sebe delaš Boga.«',
        34: 'Jezus jim je odgovoril: »Ali ni v vaši postavi zapisano: ›Rekel sem: ›Vi ste bogovi?‹‹',
        35: 'Če pa je imenoval bogove te, ki jim je prišla Božja beseda in pismo ne more biti prekršeno,',
        36: 'pravite o njem, ki ga je Oče posvetil in poslal na svet: ›Ti preklinjaš,‹ ker sem rekel, da sem Božji Sin?',
        37: 'Če ne opravljam del svojega Očeta, mi ne verjemite.',
        38: 'Toda če jih opravljam, čeprav mi ne verjamete, verjemite delom, da boste lahko spoznali in verovali, da je Oče v meni in jaz v njem.«',
        39: 'Zato so si ponovno prizadevali, da ga primejo, toda pobegnil je iz njihove roke',
        40: 'in ponovno odšel proč, onstran Jordana, na kraj, kjer je Janez najprej krščeval in tam ostal.',
        41: 'In mnogi so krenili k njemu ter rekli: »Janez ni storil nobenega čudeža, toda vse besede, ki jih je Janez govoril o tem človeku, so bile resnične.«',
        42: 'In tam so mnogi verovali vanj.',
    },
    11: {
        1: 'Torej nek mož je bil bolan, po imenu Lazar, iz Betanije, mesta Marije in njene sestre Marte.',
        2: '(Marija je bila tista, ki je Gospoda mazilila z mazilom in je s svojimi lasmi obrisala njegova stopala, katere brat Lazar je bil bolan.)',
        3: 'Zato sta njegovi sestri poslali k njemu, rekoč: »Gospod, glej, tisti, ki ga imaš rad, je bolan.«',
        4: 'Ko je Jezus to slišal, je rekel: »Ta bolezen ni za smrt, temveč za Božjo slavo, da bo Božji Sin s tem lahko proslavljen.«',
        5: 'Torej Jezus je ljubil Marto in njeno sestro ter Lazarja.',
        6: 'Ko je torej slišal, da je bil bolan, je še dva dni ostal na istem kraju, kjer je bil.',
        7: 'Šele nató reče svojim učencem: »Ponovno pojdimo v Judejo.«',
        8: 'Njegovi učenci mu rečejo: »Učitelj, Judje so si nedavno prizadevali, da te kamnajo, ti pa greš ponovno tja?«',
        9: 'Jezus je odgovoril: »Ali ni v dnevu dvanajst ur? Če katerikoli človek hodi podnevi, se ne spotika, ker vidi svetlobo tega sveta.',
        10: 'Toda če človek hodi ponoči, se spotika, ker v njem ni svetlobe.«',
        11: 'Te besede je rekel in nató jim reče: »Naš prijatelj Lazar spi, vendar grem, da ga lahko zbudim iz spanja.«',
        12: 'Tedaj so njegovi učenci rekli: »Gospod, če spi, bo okreval.«',
        13: 'Vendar je Jezus govoril o njegovi smrti, toda mislili so, da je govoril o počitku v spanju.',
        14: 'Tedaj jim je Jezus odkrito povedal: »Lazar je mrtev.',
        15: 'Zaradi vas pa sem vesel, da nisem bil tam, z namenom, da boste lahko verovali, vendar pojdimo k njemu.«',
        16: 'Tedaj je Tomaž, ki se je imenoval Dvojček, rekel svojim součencem: »Naj gremo tudi mi, da bomo lahko umrli z njim.«',
        17: 'Potem ko je Jezus prišel, je odkril, da je že štiri dni ležal v grobu.',
        18: 'Torej Betanija je bila blizu Jeruzalema, okoli petnajst dolžin brazd proč',
        19: 'in mnogi izmed Judov so prišli k Marti in Mariji, da ju tolažijo glede njunega brata.',
        20: 'Potem je Marta, takoj ko je slišala, da je prihajal Jezus, odšla in ga srečala, toda Marija je še vedno sedela v hiši.',
        21: 'Tedaj je Marta rekla Jezusu: »Gospod, če bi bil ti tukaj, moj brat ne bi umrl.',
        22: 'Toda jaz vem, da celó sedaj, karkoli hočeš prositi od Boga, ti bo Bog to dal.«',
        23: 'Jezus ji reče: »Tvoj brat bo ponovno vstal.«',
        24: 'Marta mu reče: »Vem, da bo ponovno vstal na vstajenje ob poslednjem dnevu.«',
        25: '§ Jezus ji je rekel: »Jaz sem vstajenje in življenje. Kdor vame veruje, četudi bi bil mrtev, bo vendarle živel.',
        26: 'In kdorkoli živi in veruje vame, ne bo nikoli umrl. Veruješ to?«',
        27: 'Ona mu reče: »Da, Gospod. Verujem, da si ti Kristus, Božji Sin, ki naj bi prišel na svet.«',
        28: 'In ko je tako rekla, je šla svojo pot in na skrivnem poklicala svojo sestro Marijo, rekoč: »Učitelj je prišel in te kliče.«',
        29: 'Brž ko je ona to zaslišala, je hitro vstala in prišla k njemu.',
        30: 'Torej Jezus še ni prišel v mesto, temveč je bil na kraju, kjer ga je srečala Marta.',
        31: 'Ko so Judje, ki so bili z njo v hiši in jo tolažili, videli Marijo, da je v naglici vstala in odšla ven, so ji potem sledili, rekoč: »H grobu gre, da bi tam jokala.«',
        32: 'Torej ko je Marija prišla tja, kjer je bil Jezus in ga zagledala, je padla dol k njegovim stopalom in mu rekla: »Gospod, če bi bil ti tukaj, moj brat ne bi umrl.«',
        33: 'Ko jo je Jezus torej videl jokajočo in jokajoče tudi Jude, ki so prišli z njo, je v duhu zastokal in bil vznemirjen',
        34: 'ter rekel: »Kam ste ga položili?« Rekli so mu: »Gospod, pridi in poglej.«',
        35: 'Jezus se je zjokal.',
        36: 'Tedaj so Judje rekli: »Glejte, kako ga je imel rad!«',
        37: 'Nekateri izmed njih pa so rekli: »Mar ni mogel ta človek, ki je slepemu odprl oči, storiti, da ta mož sploh ne bi umrl?«',
        38: 'Jezus torej, v sebi ponovno stokajoč, pride h grobu. To je bila votlina in nanjo je bil položen kamen.',
        39: 'Jezus je rekel: »Odstranite kamen proč.« Marta, sestra tega, ki je bil mrtev, mu reče: »Gospod, do sedaj že zaudarja, kajti mrtev je štiri dni.«',
        40: 'Jezus ji reče: »Kaj ti nisem rekel, da če boš verovala, boš videla Božjo slavo?«',
        41: 'Tedaj so odstranili kamen z mesta, kamor je bil mrtvi položen. Jezus pa je povzdignil svoje oči in rekel: »Oče, hvala ti, da si me uslišal.',
        42: 'In vedel sem, da me ti vedno uslišiš, toda to sem rekel zaradi množice, ki stoji zraven, da bi lahko verovala, da si me ti poslal.«',
        43: 'In ko je tako govoril, je z močnim glasom zaklical: »Lazar, pridi naprej.«',
        44: 'In tisti, ki je bil mrtev, je prišel naprej, z rokami in nogami, povezanimi s pogrebnimi oblačili in njegov obraz je bil naokoli povezan s prtičem. Jezus jim reče: »Odvežite ga in ga pustite oditi.«',
        45: 'Potem so mnogi izmed Judov, ki so prišli k Mariji in videli stvari, ki jih je Jezus storil, verovali vanj.',
        46: 'Toda nekateri izmed njih so odšli po svojih poteh k farizejem in jim povedali, kakšne stvari je Jezus storil.',
        47: 'Tedaj so visoki duhovniki in farizeji zbrali véliki zbor ter rekli: »Kaj [naj] storimo? Kajti ta človek dela mnoge čudeže.',
        48: 'Če ga pustimo tako pri miru, bodo vsi ljudje verovali vanj in prišli bodo Rimljani in odvzeli tako naš prostor kakor narod.«',
        49: 'In eden izmed njih, po imenu Kajfa, ki je bil to isto leto véliki duhovnik, jim je rekel: »Vi čisto nič ne veste,',
        50: 'niti ne preudarite, da je za nas koristno, da naj bi en človek umrl za ljudi, ne pa da propade celoten narod.«',
        51: 'To pa ni govoril [sam] od sebe, temveč ker je bil tisto leto véliki duhovnik, je prerokoval, da naj bi Jezus umrl za ta narod,',
        52: 'in ne samo za ta narod, temveč da naj bi tudi Božje otroke, ki so bili razkropljeni naokoli, skupaj zbral v enem.',
        53: 'Torej so se od tega dne dalje skupaj posvetovali, da ga usmrtijo.',
        54: 'Jezus torej med Judi ni več hodil javno, temveč je od tam odšel v deželo poleg divjine, v mesto, imenovano Efrájim in tam ostal s svojimi učenci.',
        55: 'In blizu je bila judovska pasha in mnogi iz dežele so pred pasho odšli gor v Jeruzalem, da se očistijo.',
        56: 'Medtem ko so stali v templju, so torej iskali Jezusa in med seboj govorili: »Kaj mislite, da ne bo prišel na praznik?«',
        57: 'Torej tako visoki duhovniki kakor farizeji so izdali zapoved, da če katerikoli človek ve, kje bi bil, naj to pokaže, da bi ga lahko prijeli.',
    },
    12: {
        1: 'Potem je Jezus, šest dni pred pasho, prišel v Betanijo, kjer je bil Lazar, ki je bil mrtev, ki ga je obudil od mrtvih.',
        2: 'Tam so mu pripravili večerjo in Marta je stregla, toda Lazar je bil eden izmed teh, ki je z njim sedel za mizo.',
        3: 'Tedaj je Marija vzela funt zelo dragocenega mazila iz narde in mazilila Jezusova stopala in s svojimi lasmi obrisala njegova stopala, in hiša je bila napolnjena z vonjem mazila.',
        4: '§ Potem reče eden izmed njegovih učencev, Juda Iškarijot, Simonov sin, ki naj bi ga izdal:',
        5: '»Zakaj ni bilo to mazilo prodano za tristo denarjev in dano revnim?«',
        6: '§ To je rekel, ne, ker bi skrbel za revne, temveč zato, ker je bil tat in je imel mošnjo ter nosil, kar je bilo dano vanjo.',
        7: 'Potem je Jezus rekel: »Pusti jo pri miru. To je zadržala za dan mojega pokopa.',
        8: 'Kajti revne imate vedno s seboj, mene pa nimate vedno.«',
        9: 'Veliko ljudi izmed Judov je torej vedelo, da je bil tam. Niso pa prišli samo zaradi Jezusa, temveč, da bi lahko videli tudi Lazarja, ki ga je obudil od mrtvih.',
        10: 'Toda visoki duhovniki so se posvetovali, da bi mogli usmrtiti tudi Lazarja,',
        11: 'zato ker je zaradi tega razloga mnogo izmed Judov odšlo proč in verovalo v Jezusa.',
        12: 'Naslednji dan je mnogo ljudi, ki so prišli na praznik, ko so slišali, da je v Jeruzalem prihajal Jezus,',
        13: 'vzelo mladike palmovih dreves in mu odšlo naproti, da ga srečajo ter klicali: »Hozana: ›Blagoslovljen je Izraelov Kralj, ki prihaja v Gospodovem imenu.‹«',
        14: 'In Jezus, ko je našel mladega osla, je sédel nanj, kakor je pisano:',
        15: '»Ne boj se, hči sionska, glej, tvoj Kralj prihaja, sedeč na osličjem žrebetu.«',
        16: 'Teh stvari njegovi učenci sprva niso razumeli, toda ko je bil Jezus poveličan, potem so se spomnili, da so bile te stvari pisane o njem in da so mu te stvari storili.',
        17: 'Množica torej, ki je bila z njim, ko je Lazarja poklical iz njegovega groba in ga obudil od mrtvih, je pričevala.',
        18: 'Zaradi tega razloga ga je množica tudi srečala, ker so slišali, da je storil ta čudež.',
        19: 'Farizeji so torej med seboj govorili: » [Ali] ne zaznate, kako ničesar ne prevladate? Glejte, svet je odšel za njim.«',
        20: 'In med njimi so bili neki Grki, ki so ob prazniku prišli gor oboževat.',
        21: 'Isti so torej prišli k Filipu, ki je bil iz Betsajde v Galileji in ga prosili, rekoč: »Gospod, mi bi videli Jezusa.«',
        22: 'Filip prihaja ter pove Andreju in prav tako Andrej ter Filip povesta Jezusu.',
        23: 'In Jezus jima je odgovoril, rekoč: »Ura je prišla, da naj bi bil Sin človekov poveličan.',
        24: 'Resnično, resnično, povem vam: ›Razen če pšenično zrno ne pade na tla in ne umre, ostaja sámo; toda če umre, obrodi mnogo sadu.‹',
        25: 'Kdor ima rad svoje življenje, ga bo izgubil; kdor pa svoje življenje na tem svetu sovraži, ga bo ohranil za večno življenje.',
        26: 'Če katerikoli človek služi meni, naj mi sledi; in kjer sem jaz, tam bo tudi moj služabnik. Če katerikoli človek služi meni, ga bo moj Oče počastil.',
        27: 'Sedaj je moja duša vznemirjena in kaj naj rečem? ›Oče, reši me pred to uro.‹ Toda zaradi tega razloga sem prišel v to uro.',
        28: '›Oče, proslavi svoje ime.‹« Tedaj je tja prišel glas iz nebes, rekoč: »Proslavil sem ga in ponovno ga bom proslavil.«',
        29: 'Množica torej, ki je stala poleg in to slišala, je rekla, da je zagrmelo; drugi so rekli: »Angel mu je govoril.«',
        30: 'Jezus je odgovoril in rekel: »Ta glas ni prišel zaradi mene, temveč zaradi vas.',
        31: 'Sedaj je sodba tega sveta. Sedaj bo princ tega sveta izgnan ven.',
        32: '§ In jaz, če bom povzdignjen z zemlje, bom k sebi pritegnil vse ljudi.«',
        33: 'To je rekel, ker je naznanil, kakšne smrti naj bi umrl.',
        34: 'Množica mu je odgovorila: »Iz postave smo slišali, da Kristus ostaja večno; in kako praviš ti: ›Sin človekov mora biti dvignjen?‹ Kdo je ta Sin človekov?«',
        35: 'Potem jim je Jezus rekel: »Še malo časa je z vami svetloba. Hodíte, dokler imate svetlobo, da ne bi nad vas prišla tema, kajti kdor hodi v temi, ne ve, kam gre.',
        36: 'Dokler imate svetlobo, verujte v svetlobo, da boste lahko otroci svetlobe.« Te besede je govoril Jezus in odšel ter se skril pred njimi.',
        37: 'Toda čeprav je pred njimi storil toliko čudežev, kljub temu niso verovali vanj,',
        38: 'da se je lahko izpolnila beseda preroka Izaija, ki je govoril: ›Gospod, kdo je veroval našemu poročilu in komu se je razodel Gospodov laket?‹',
        39: 'Torej niso mogli verovati, zato ker je ta Izaija ponovno rekel:',
        40: '›Oslepel je njihove oči in zakrknil njihovo srce, da ne bi mogli videti s svojimi očmi niti razumeti s svojim srcem in ne bi bili spreobrnjeni in bi jih jaz ne ozdravil.‹',
        41: 'Te besede je izrekel Izaija, ko je videl njegovo slavo in govoril o njem.',
        42: 'Vendar so tudi med visokimi vladarji mnogi verovali vanj, toda zaradi farizejev ga niso priznali, da ne bi bili izločeni iz sinagoge,',
        43: 'kajti bolj so ljubili hvalo ljudi kakor Božjo hvalo.',
        44: 'Jezus je zaklical in rekel: »Kdor veruje vame, ne veruje vame, temveč v tistega, ki me je poslal.',
        45: 'In kdor vidi mene, vidi tistega, ki me je poslal.',
        46: 'Prišel sem, svetloba na svet, da kdorkoli veruje vame, ne bi ostal v temi.',
        47: 'In če katerikoli človek sliši moje besede in ne veruje, ga ne sodim jaz, kajti nisem prišel, da svet sodim, temveč da svet rešim.',
        48: 'Kdor zavrača mene in ne sprejema mojih besed, ima nekoga, ki ga sodi. Beseda, ki sem jo govoril, ta ista ga bo sodila na poslednji dan.',
        49: 'Kajti nisem govoril sam od sebe, temveč Oče, ki me je poslal, mi je dal zapoved, kaj naj rečem in kaj naj govorim.',
        50: 'In jaz vem, da je njegova zapoved večno življenje. Karkoli torej govorim, govorim tako, celó kakor mi je rekel Oče.«',
    },
    13: {
        1: 'Torej pred praznikom pashe, ko je Jezus spoznal, da je prišla njegova ura, da naj bi odšel s tega sveta k Očetu in ker je ljubil svoje, ki so bili na svetu, jih je ljubil do konca.',
        2: 'In ko se je večerja končala, je torej hudič Judu Iškarijotu, Simonovemu sinu, v srce položil, da ga izda.',
        3: 'Ker je Jezus vedel, da je Oče vse stvari dal v njegove roke in da je prišel od Boga in odšel k Bogu,',
        4: 'se dvigne od večerje in odloži svoje obleke in vzame brisačo ter se opaše.',
        5: 'Nató vlije vodo v umivalnik in začne učencem umivati stopala ter jih brisati z brisačo, s katero je bil opasan.',
        6: 'Potem pride k Simonu Petru in Peter mu reče: »Gospod, ti mi umivaš moja stopala?«',
        7: 'Jezus je odgovoril in mu rekel: »Kar delam, ti sedaj ne veš, toda spoznal boš pozneje.«',
        8: 'Peter mu reče: »Nikoli ne boš umival mojih stopal.« Jezus mu je odgovoril: »Če te ne umijem, nimaš deleža z menoj.«',
        9: 'Simon Peter mu reče: »Gospod, ne samo mojih stopal, temveč tudi moje roke in mojo glavo.«',
        10: 'Jezus mu reče: »Kdor je umit, se mu razen svojih stopal ni treba umiti, ampak je čist vsak delček; in vi ste čisti, toda ne vsi.«',
        11: 'Kajti vedel je, kdo naj bi ga izdal, zato je rekel: »Niste vsi čisti.«',
        12: 'Torej potem, ko jim je umil njihova stopala in vzel svoje obleke ter se ponovno usedel, jim je rekel: »Ali veste, kaj sem vam storil?',
        13: 'Vi me kličete Učitelj in Gospod, in pravilno govorite, kajti to sem.',
        14: 'Če sem vam torej jaz, vaš Gospod in Učitelj, umil vaša stopala, morate tudi vi drug drugemu umivati stopala.',
        15: 'Kajti dal sem vam zgled, da bi tudi vi delali tako, kakor sem vam storil jaz.',
        16: 'Resnično, resnično, povem vam: ›Služabnik ni večji kakor njegov gospodar; niti kdor je poslan, ni večji kakor tisti, ki ga je poslal.',
        17: 'Če poznate te stvari, ste srečni, če jih izvršujete.',
        18: 'Ne govorim o vas vseh. Vem, katere sem izbral, toda da bi se lahko izpolnilo pismo: ›Kdor jé kruh z menoj, je dvignil svojo peto zoper mene.‹',
        19: 'Sedaj vam pravim, preden pride, da ko se zgodi, boste lahko verovali, da jaz sem.',
        20: 'Resnično, resnično, povem vam: ›Kdor sprejme, kogarkoli jaz pošljem, sprejme mene; in kdor sprejme mene, sprejme tistega, ki me je poslal.‹«',
        21: 'Ko je Jezus tako rekel, je bil v duhu vznemirjen in pričeval ter rekel: »Resnično, resnično, povem vam, da me bo eden izmed vas izdal.«',
        22: 'Potem so učenci pogledali drug na drugega, dvomeč, o kom je govoril.',
        23: 'Torej na Jezusovo naročje je bil naslonjen eden izmed njegovih učencev, ki ga je Jezus ljubil.',
        24: 'Simon Peter mu je torej dal znamenje, da naj vpraša, kdo bi bil ta, o katerem je govoril.',
        25: 'On mu potem, ležeč na Jezusovih prsih, reče: »Gospod, kdo je ta?«',
        26: 'Jezus je odgovoril: »To je tisti, ki mu bom dal grižljaj, ko ga bom pomočil.« In ko je grižljaj pomočil, ga je dal Judu Iškarijotu, Simonovemu sinu.',
        27: 'In po grižljaju je vanj vstopil Satan. Tedaj mu je Jezus rekel: »To, kar delaš, stôri hitro.«',
        28: 'Torej noben človek pri mizi ni vedel, za kakšen namen mu je to rekel.',
        29: 'Kajti nekateri izmed njih so mislili, ker je imel Juda mošnjo, da mu je Jezus rekel: »Kupi te stvari, ki jih potrebujemo za praznik,« ali da naj bi nekaj dal ubogim.',
        30: 'Potem ko je prejel grižljaj, je takoj odšel ven; bila pa je noč.',
        31: 'Torej ko je odšel ven, je Jezus rekel: »Sedaj je Sin človekov proslavljen in Bog je proslavljen v njem.',
        32: 'Če je Bog proslavljen v njem, bo tudi Bog njega proslavil v sebi in nemudoma ga bo proslavil.',
        33: 'Majhni otroci, še malo časa sem z vami. Iskali me boste in kakor sem rekel Judom: ›Kamor grem jaz, vi ne morete priti,‹ tako sedaj pravim vam.',
        34: 'Dajem vam novo zapoved: ›Da ljubite drug drugega, kakor sem vas jaz ljubil, da tudi vi ljubite drug drugega.',
        35: 'Po tem bodo vsi ljudje spoznali, da ste moji učenci, če imate drug do drugega ljubezen.‹«',
        36: 'Simon Peter mu je rekel: »Gospod, kam greš?« Jezus mu je odgovoril: »Kamor jaz grem, mi sedaj ne moreš slediti, toda sledil mi boš pozneje.«',
        37: 'Peter mu je rekel: »Gospod, zakaj ti ne morem slediti sedaj? Svoje življenje hočem dati zaradi tebe.«',
        38: 'Jezus mu je odgovoril: »Življenje hočeš dati zaradi mene? Resnično, resnično, povem ti: ›Petelin ne bo zapel, dokler me trikrat ne zanikaš.‹«',
    },
    14: {
        1: '»Ne dopustite, da bi bilo vaše srce vznemirjeno. Verujte v Boga, tudi vame verujte.',
        2: 'V hiši mojega Očeta je mnogo graščin. Če ne bi bilo tako, bi vam povedal. Grem, da pripravim prostor za vas.',
        3: 'Če pa grem in pripravim prostor za vas, bom ponovno prišel in vas sprejel k sebi, da kjer sem jaz, boste tam lahko tudi vi.',
        4: '§ In kamor jaz grem, veste in pot poznate.«',
        5: 'Tomaž mu reče: »Gospod, ne vemo, kam greš in kako moremo poznati pot?«',
        6: 'Jezus mu reče: »Jaz sem pot, resnica in življenje. Nihče ne pride k Očetu, razen po meni.',
        7: 'Če bi spoznali mene, bi spoznali tudi mojega Očeta in odslej ga poznate in ste ga videli.«',
        8: 'Filip mu reče: »Gospod, pokaži nam Očeta in to nam zadošča.«',
        9: 'Jezus mu reče: »Filip, toliko časa sem bil z vami, pa me vendar nisi spoznal? Kdor je videl mene, je videl Očeta, in kako potem praviš: ›Pokaži nam Očeta?‹',
        10: 'Ne verjameš, da sem jaz v Očetu in Oče v meni? Besede, ki vam jih govorim, ne govorim sam od sebe, temveč Oče, ki prebiva v meni, on opravlja dela.',
        11: 'Verjemite mi, da sem v Očetu in Oče v meni; če pa ne, mi verjemite zaradi del samih.',
        12: 'Resnično, resnično, povem vam: ›Kdor veruje vame, bo dela, ki jih jaz opravljam, tudi sam opravljal; in opravljal bo večja dela kakor ta, ker grem k svojemu Očetu.',
        13: 'In karkoli boste zahtevali v mojem imenu, bom to storil, da bo Oče lahko proslavljen v Sinu.',
        14: 'Če boste karkoli zahtevali v mojem imenu, bom jaz to storil.‹',
        15: 'Če ljubite mene, se držite mojih zapovedi.',
        16: 'In prosil bom Očeta in dal vam bo drugega Tolažnika, da bo lahko večno ostal z vami,',
        17: 'celó Duha resnice, ki ga svet ne more prejeti zato, ker ga ne vidi niti ga ne pozna. Toda vi ga poznate, kajti on prebiva z vami in bo v vas.',
        18: 'Ne bom vas zapustil brez tolažbe. Prišel bom k vam.',
        19: 'Še malo časa in svet me ne vidi več, toda vi me vidite. Ker jaz živim, boste živeli tudi vi.',
        20: 'Na tisti dan boste vedeli, da jaz sem v svojem Očetu in vi v meni in jaz v vas.',
        21: 'In kdor ima moje zapovedi in se jih drži, je tisti, ki me ljubi. In kdor ljubi mene, bo ljubljen od mojega Očeta in jaz ga bom ljubil in se mu bom razodel.«',
        22: 'Juda, ne Iškarijot, mu reče: »Gospod, kako to, da se hočeš razodeti nam, ne pa svetu?«',
        23: 'Jezus je odgovoril in mu rekel: »Če me človek ljubi, se bo držal mojih besed in moj Oče ga bo ljubil in prišla bova k njemu in naredila prebivališče z njim.',
        24: 'In kdor me ne ljubi, se ne drži mojih izjav. In beseda, ki jo slišite, ni moja, temveč od Očeta, ki me je poslal.',
        25: 'Te stvari sem vam govoril, ko sem bil še prisoten z vami.',
        26: 'Toda Tolažnik, ki je Sveti Duh, ki ga bo Oče poslal v mojem imenu, vas bo učil vseh stvari in vam bo v vaš spomin privedel vse besede, karkoli sem vam povedal.',
        27: 'Mir zapustim z vami, svoj mir vam dam. Ne kakor daje svet, vam ga jaz dam. Ne dopustite, da bi bila vaša srca vznemirjena niti naj ne bodo prestrašena.',
        28: 'Slišali ste, kako sem vam rekel: ›Jaz grem proč in ponovno pridem k vam.‹ Če ste ljubili mene, bi se razveselili, ker sem rekel: ›Jaz grem k Očetu,‹ kajti moj Oče je večji od mene.',
        29: 'In sedaj sem vam povedal, preden se zgodi, da boste lahko verovali, ko se zgodi.',
        30: 'Odslej ne bom več veliko govoril z vami, kajti princ tega sveta prihaja, toda v meni nima ničesar.',
        31: 'Toda, da bo svet lahko spoznal, da ljubim Očeta in kakor mi je Oče dal zapoved, točno tako delam jaz. Vstanite, pojdimo od tod.«',
    },
    15: {
        1: '»Jaz sem resnična vinska trta in moj Oče je poljedelec.',
        2: 'Vsako mladiko na meni, ki ne prinaša sadu, on odstranja in vsako vejo, ki prinaša sad, očiščuje, da bo lahko obrodila več sadu.',
        3: 'Torej vi ste čisti po besedi, ki sem vam jo govoril.',
        4: 'Ostanite v meni in jaz v vas. Kakor mladika sama od sebe ne more obroditi sadu, razen če ne ostane na vinski trti, nič bolj ne morete vi, razen če ne ostanete v meni.',
        5: 'Jaz sem trta, vi ste mladike. Kdor ostaja v meni in jaz v njem, ta isti prinaša obilo sadu, kajti brez mene ne morete storiti ničesar.',
        6: 'Če človek ne ostane v meni, je odvržen kakor mladika in se posuši; in ljudje jih zberejo ter jih vržejo v ogenj in so sežgane.',
        7: 'Če ostanete v meni in moje besede ostanejo v vas, boste prosili, kar hočete in se vam bo to zgodilo.',
        8: 'V tem je moj Oče proslavljen, da obrodite obilo sadu; tako boste postali moji učenci.',
        9: 'Kakor je Oče mene ljubil, tako sem jaz vas ljubil. Ostanite v moji ljubezni.',
        10: 'Če se držite mojih zapovedi, boste ostali v moji ljubezni; kakor sem se jaz držal Očetovih zapovedi in ostajam v njegovi ljubezni.',
        11: 'Te besede sem vam govoril, da moja radost lahko ostane v vas in da bo vaša radost lahko popolna.',
        12: 'To je moja zapoved: ›Da ljubite drug drugega, kakor sem vas jaz ljubil.‹',
        13: 'Nihče nima večje ljubezni, kakor je ta, da človek svoje življenje žrtvuje za svoje prijatelje.',
        14: 'Vi ste moji prijatelji, če storite, karkoli vam zapovem.',
        15: 'Odslej vas ne imenujem služabnike, kajti služabnik ne ve, kaj dela njegov gospodar; toda vas sem imenoval prijatelje, kajti dal sem vam spoznati vse stvari, ki sem jih slišal od svojega Očeta.',
        16: 'Niste vi mene izbrali, ampak sem jaz izbral vas in vam odredil, da bi šli in obrodili sad in da bi vaš sad ostal, da karkoli boste zahtevali od mojega Očeta v mojem imenu, vam bo on to lahko dal.',
        17: 'Te besede vam zapovedujem, da ljubite drug drugega.',
        18: 'Če vas svet sovraži, vedite, da je mene sovražil, preden je sovražil vas.',
        19: 'Če bi bili od sveta, bi svet svoje imel rad, toda ker niste od sveta, temveč sem vas izbral od sveta, vas torej svet sovraži.',
        20: 'Spomnite se besede, ki sem vam jo rekel: ›Služabnik ni večji kot njegov gospodar.‹ Če so preganjali mene, bodo prav tako preganjali vas; če so se držali mojih izjav, se bodo držali tudi vaših.',
        21: 'Toda vse te stvari vam bodo storili zaradi mojega imena, ker ne poznajo tistega, ki me je poslal.',
        22: 'Če ne bi prišel in jim ne bi govoril, ne bi imeli greha, toda sedaj za svoj greh nimajo nobene pretveze.',
        23: 'Kdor sovraži mene, sovraži tudi mojega Očeta.',
        24: 'Če med njimi ne bi storil del, ki jih noben drug človek ni storil, ne bi imeli greha, toda sedaj so tako videli kakor sovražili, tako mene kakor mojega Očeta.',
        25: 'Toda to se dogaja, da se bo lahko izpolnila beseda, ki je zapisana v njihovi postavi: ›Sovražili so me brez razloga.‹',
        26: 'Toda ko pride Tolažnik, ki ga bom poslal k vam od Očeta, celó Duh resnice, ki izvira od Očeta, bo on pričeval o meni;',
        27: 'in tudi vi boste pričevali, ker ste bili od začetka z menoj.«',
    },
    16: {
        1: '»Te besede sem vam govoril, da se ne bi pohujšali.',
        2: 'Izločali vas bodo iz sinagog; da, prihaja čas, da bo, kdorkoli vas ubija, mislil, da opravlja službo Bogu.',
        3: 'In te stvari vam bodo počeli, ker niso spoznali niti Očeta niti mene.',
        4: 'Toda te stvari sem vam povedal, da se boste lahko spomnili, ko bo prišel čas, da sem vam povedal o njih. Teh stvari pa vam na začetku nisem povedal, ker sem bil z vami.',
        5: 'Toda sedaj grem svojo pot k njemu, ki me je poslal, pa me nihče izmed vas ne vpraša: ›Kam greš?‹',
        6: 'Toda ker sem vam povedal te stvari, je vaše srce napolnila bridkost.',
        7: 'Vendar vam govorim resnico. Za vas je koristno, da odidem, kajti če ne odidem, potem Tolažnik ne bo prišel k vam, toda če odidem, vam ga bom poslal.',
        8: 'In ko on pride, bo grajal svet o grehu in o pravičnosti in o sodbi:',
        9: 'o grehu, ker ne verujejo vame;',
        10: 'o pravičnosti, ker grem k svojemu Očetu in me ne boste več videli;',
        11: 'o sodbi, ker je princ tega sveta obsojen.',
        12: 'Imam vam povedati še mnogo stvari, toda sedaj jih ne morete nositi.',
        13: 'Vendar ko pride on, Duh resnice, vas bo usmerjal v vso resnico, kajti ne bo govoril iz sebe, temveč karkoli bo slišal, to bo govoril in pokazal vam bo stvari, ki pridejo.',
        14: 'On me bo proslavil, kajti prejel bo od mojega in vam bo to pokazal.',
        15: 'Vse stvari, ki jih ima Oče, so moje. Torej sem rekel, da bo vzel od mojega in vam bo to pokazal.',
        16: '§ Malo časa in me ne boste videli in ponovno, malo časa in me boste videli, ker grem k Očetu.«',
        17: 'Tedaj so nekateri izmed njegovih učencev med seboj govorili: »Kaj je to, da nam pravi: ›Malo časa in me ne boste videli, in ponovno, malo časa in me boste videli‹ in: ›Ker grem k Očetu?‹«',
        18: 'Rekli so torej: »Kaj je to, kar pravi: ›Malo časa?‹ Ne moremo povedati, kaj pravi.«',
        19: 'Torej Jezus je vedel, da so ga bili željni vprašati in jim je rekel: »Ali med seboj povprašujete, ker sem rekel: ›Malo časa in me ne boste videli, in ponovno, malo časa in me boste videli?‹',
        20: 'Resnično, resnično, povem vam: ›Da boste jokali in žalovali, toda svet se bo veselil; vi pa boste žalostni, toda vaša žalost bo obrnjena v radost.‹',
        21: 'Ženska, ko je v porodnih mukah, ima bridkost, ker je prišla njena ura; toda takoj, ko je razbremenjena otroka, se zaradi radosti, da je človek rojen na svet, ne spominja več tesnobe.',
        22: 'In zato imate sedaj bridkost. Toda ponovno vas bom videl in vaše srce se bo veselilo in vaše radosti vam nihče ne bo odvzel.',
        23: 'In na tisti dan me ne boste ničesar vprašali. Resnično, resnično, povem vam: ›Karkoli boste zahtevali od Očeta v mojem imenu, vam bo to dal.‹',
        24: 'Doslej niste ničesar zahtevali v mojem imenu. Zahtevajte in boste prejeli, da bo vaša radost lahko popolna.',
        25: 'Te stvari sem vam govoril v pregovorih, toda prihaja čas, ko vam ne bom več govoril v pregovorih, temveč vam bom o Očetu odkrito pokazal.',
        26: 'Na tisti dan boste prosili v mojem imenu, in ne pravim vam, da bom jaz prosil Očeta za vas,',
        27: 'kajti sam Oče vas ima rad, ker ste me imeli radi in ste verovali, da sem prišel od Boga.',
        28: 'Prišel sem od Očeta in prišel sem na svet; zopet zapustim svet in grem k Očetu.«',
        29: 'Njegovi učenci so mu rekli: »Glej, sedaj govoriš odkrito in ne govoriš pregovora.',
        30: 'Sedaj smo prepričani, da veš vse stvari in ne potrebuješ, da bi te katerikoli človek vprašal. Po tem verujemo, da si prišel od Boga.«',
        31: 'Jezus jim je odgovoril: »Sedaj verujete?',
        32: 'Glejte, prihaja ura, da, pravkar je prišla, da boste razkropljeni, vsak k svojemu lastnemu, mene pa boste pustili samega; in vendar nisem sam, ker je Oče z menoj.',
        33: 'Te stvari sem vam govoril, da boste lahko imeli mir v meni. Na svetu boste imeli stisko, toda bodite dobre volje, jaz sem svet premagal.«',
    },
    17: {
        1: 'Te besede je govoril Jezus in svoje oči povzdignil k nebu ter rekel: »Oče, prišla je ura; proslavi svojega Sina, da bo lahko tudi tvoj Sin proslavil tebe,',
        2: 'kakor si mu izročil oblast nad vsem mesom, da bi on lahko dal večno življenje tolikim, kolikor si mu jih dal.',
        3: 'In to je večno življenje, da bi oni lahko spoznali tebe, edinega resničnega Boga in Jezusa Kristusa, ki si ga poslal.',
        4: 'Jaz sem te proslavil na zemlji. Končal sem delo, ki si mi ga dal, da ga opravim.',
        5: 'In sedaj, oh Oče, me proslavi pri samem sebi s slavo, ki sem jo imel s teboj, preden je bil svet.',
        6: 'Jasno sem pokazal tvoje ime ljudem, ki mi jih daješ ven iz sveta. Bili so tvoji in ti jih daješ meni in ohranili so tvojo besedo.',
        7: 'Sedaj so spoznali, da so vse stvari, katerekoli si mi dal, od tebe.',
        8: 'Kajti dal sem jim besede, ki jih ti daješ meni in sprejeli so jih in zagotovo so spoznali, da sem prišel od tebe in verovali so, da si me ti poslal.',
        9: 'Jaz prosim zanje. Ne prosim za svet, temveč za tiste, ki si mi jih ti dal, kajti tvoji so.',
        10: 'In vse moje je tvoje in tvoje je moje in proslavljen sem v njih.',
        11: 'In sedaj nisem več na svetu, toda ti so na svetu, jaz pa prihajam k tebi. Sveti Oče, po svojem lastnem imenu ohrani te, ki si mi jih dal, da bodo lahko eno, kakor sva midva.',
        12: '§ Dokler sem bil z njimi na svetu, sem jih varoval v tvojem imenu. Te, ki mi jih daješ, sem obvaroval in nihče izmed njih ni izgubljen, razen sina pogube, da se lahko izpolni pismo.',
        13: 'In sedaj prihajam k tebi in te stvari govorim na svetu, da bodo mojo radost lahko imeli v sebi izpolnjeno.',
        14: 'Dal sem jim tvojo besedo, svet pa jih je sovražil, ker niso od sveta, celó kakor jaz nisem od sveta.',
        15: 'Ne prosim, da bi jih vzel iz sveta, temveč, da bi jih varoval pred zlom.',
        16: 'Niso od sveta, celó kakor jaz nisem od sveta.',
        17: 'Posvetí jih po svoji resnici. Tvoja beseda je resnica.',
        18: 'Kakor si me ti poslal v svet, točno tako sem jih tudi jaz poslal v svet.',
        19: 'In zaradi njih se posvečujem, da bodo tudi oni lahko posvečeni preko resnice.',
        20: 'Niti ne prosim samo za té, temveč tudi za tiste, ki bodo po njihovi besedi verovali vame,',
        21: 'da bi bili lahko vsi eno, kakor si ti, Oče, v meni in jaz v tebi, da bi bili lahko tudi oni eno v nas [treh], da bi svet lahko veroval, da si me ti poslal.',
        22: 'In slavo, ki mi jo daješ, sem dal njim, da bodo lahko eno, tako kakor smo mi [trije] eno;',
        23: 'jaz v njih in ti v meni, da bodo lahko izpopolnjeni v enem in da bo svet lahko spoznal, da si me ti poslal in da si jih ljubil, kakor si ljubil mene.',
        24: 'Oče, hočem, da bodo tudi tisti, ki si mi jih dal, z menoj, kjer sem jaz, da bodo lahko gledali mojo slavo, ki si mi jo dal, kajti ljubil si me pred ustanovitvijo sveta.',
        25: 'Oh pravični Oče, svet te ni spoznal, toda jaz sem te spoznal in ti so spoznali, da si me ti poslal.',
        26: 'In razglasil sem jim tvoje ime in ga bom razglašal, da bo ljubezen, s katero si me ljubil, lahko v njih in jaz v njih.«',
    },
    18: {
        1: 'Ko je Jezus povedal te besede, je s svojimi učenci odšel čez potok Cedron, kjer je bil vrt, v katerega je vstopil on in njegovi učenci.',
        2: 'In tudi Juda, ki ga je izdal, je poznal kraj, kajti Jezus se je s svojimi učenci pogosto napotil tja.',
        3: 'Juda je potem, ko je od visokih duhovnikov in farizejev prejel četo mož in častnikov, prihajal tja s svetilkami, baklami in orožjem.',
        4: 'Jezus je torej, vedoč vse stvari, ki naj bi prišle nadenj, šel naprej in jim rekel: »Koga iščete?«',
        5: 'Odgovorili so mu: »Jezusa Nazarečana.« Jezus jim reče: »Jaz sem.« In tudi Juda, ki ga je izdal, je stal z njimi.',
        6: 'Takoj potem, ko jim je rekel: »Jaz sem,« so stopili nazaj in padli na tla.',
        7: 'Potem jih je ponovno vprašal: »Koga iščete?« In rekli so: »Jezusa Nazarečana.«',
        8: 'Jezus je odgovoril: »Povedal sem vam, da jaz sem. Če torej iščete mene, pustite te oditi svojo pot,«',
        9: 'da bi se lahko izpolnila beseda, ki jo je govoril: »Izmed teh, ki mi jih daješ, nisem izgubil nobenega.«',
        10: 'Takrat je Simon Peter, ki je imel meč, tega izvlekel in udaril služabnika vélikega duhovnika in odsekal njegovo desno uho. Služabnikovo ime je bilo Malh.',
        11: 'Tedaj je Jezus rekel Petru: »Spravi svoj meč v nožnico. Ali naj ne izpijem čaše, ki mi jo je dal moj Oče?«',
        12: 'Tedaj so četa in stotnik in judovski častniki vzeli Jezusa ter ga zvezali',
        13: 'in ga odvedli najprej k Hanu, kajti bil je tast Kajfu, ki je bil to isto leto véliki duhovnik.',
        14: 'Torej Kajfa je bil tisti, ki je Judom dal nasvet, da je bilo koristno, da bi en človek umrl za ljudi.',
        15: 'Simon Peter pa je sledil Jezusu in tako je storil [tudi] drug učenec. Ta učenec je bil poznan vélikemu duhovniku in je z Jezusom vstopil v palačo vélikega duhovnika.',
        16: 'Toda Peter je stal zunaj pri vratih. Potem je odšel ven ta drugi učenec, ki je bil poznan vélikemu duhovniku in spregovoril njej, ki je stražila vrata in Petra privedel noter.',
        17: 'Tedaj reče Petru gospodična, ki je stražila vrata: »Ali nisi tudi ti eden izmed učencev tega človeka?« Reče ji: »Nisem.«',
        18: 'In tam so stali služabniki in častniki, ki so pripravili žerjavico, kajti bilo je hladno in so se greli, in Peter je stal z njimi ter se grel.',
        19: 'Véliki duhovnik je tedaj vprašal Jezusa o njegovih učencih in o njegovem nauku.',
        20: 'Jezus mu je odgovoril: »Javno sem govoril svetu, vselej sem učil v sinagogi in v templju, kamor Judje vedno zahajajo in ničesar nisem povedal na skrivnem.',
        21: 'Zakaj sprašuješ mene? Vprašaj tiste, ki so me slišali, kaj sem jim povedal. Glej, vedo, kaj sem rekel.«',
        22: 'In ko je tako govoril, je eden izmed častnikov, ki je stal poleg, z dlanjo svoje roke udaril Jezusa, rekoč: »Tako odgovarjaš vélikemu duhovniku?«',
        23: 'Jezus mu je odgovoril: »Če sem govoril zlo, pričuj o zlu; toda če dobro, zakaj me tolčeš?«',
        24: 'Torej ga je Hana zvezanega poslal k vélikemu duhovniku Kajfu.',
        25: 'Simon Peter pa je stal in se grel. Torej so mu rekli: »Mar nisi tudi ti eden izmed njegovih učencev?« To je zanikal in rekel: »Nisem.«',
        26: 'Eden izmed služabnikov vélikega duhovnika, sorodnik tistega, čigar uho je Peter odsekal, reče: »Ali te nisem videl z njim na vrtu?«',
        27: 'Tedaj je Peter ponovno zanikal in petelin je takoj zapel.',
        28: 'Potem so od Kajfa Jezusa odvedli v sodno dvorano; in bilo je zgodaj, oni sami pa niso odšli v sodno dvorano, da ne bi bili omadeževani, temveč da bi smeli jesti pashalno jagnje.',
        29: 'Pilat je potem odšel ven k njim in rekel: »Kakšno obtožbo ste prinesli zoper tega človeka?«',
        30: 'Odgovorili so mu in mu rekli: »Če bi ne bil hudodelec, bi ti ga ne izročili.«',
        31: 'Tedaj jim je Pilat rekel: »Vzemite ga in ga sodite glede na svojo postavo.« Judje so mu torej rekli: »Za nas ni zakonito, da usmrtimo kateregakoli človeka,«',
        32: 'da bi se lahko izpolnila Jezusova beseda, ki jo je govoril, ko je naznanil, kakšne smrti naj bi umrl.',
        33: 'Tedaj je Pilat ponovno vstopil v sodno dvorano in poklical Jezusa ter mu rekel: »Ali si ti judovski Kralj?«',
        34: 'Jezus mu je odgovoril: »Praviš to besedo sam od sebe ali so ti to drugi povedali o meni?«',
        35: 'Pilat je odgovoril: »Sem mar Jud? Tvoj narod in visoki duhovniki so te izročili meni. Kaj si storil?«',
        36: 'Jezus je odgovoril: »Moje kraljestvo ni od tega sveta. Če bi bilo moje kraljestvo od tega sveta, potem bi se moji služabniki bojevali, da ne bi bil izročen Judom, toda sedaj moje kraljestvo ni od tod.«',
        37: 'Pilat mu je torej rekel: »Ali si ti potem kralj?« Jezus je odgovoril: »Ti praviš, da sem kralj. Za ta namen sem bil rojen in zaradi tega razloga sem prišel na svet, da naj bi pričeval k resnici. Vsak, kdor je iz resnice, posluša moj glas.«',
        38: 'Pilat mu reče: »Kaj je resnica?« In ko je to rekel, je ponovno odšel k Judom in jim reče: »Na njem sploh ne najdem nobene krivde.',
        39: 'Ampak vi imate navado, da naj bi vam za pasho enega izpustil. Hočete torej, da vam izpustim judovskega Kralja?«',
        40: 'Potem so vsi ponovno zavpili, rekoč: »Ne tega človeka, temveč Baraba.« Torej Baraba je bil razbojnik.',
    },
    19: {
        1: 'Tedaj je torej Pilat vzel Jezusa in ga prebičal.',
        2: 'In vojaki so iz trnja spletli krono in jo položili na njegovo glavo in nanj nadeli škrlatno svečano oblačilo',
        3: 'ter rekli: »Pozdravljen, judovski Kralj!« in ga udarjali s svojimi rokami.',
        4: 'Pilat je torej ponovno odšel naprej, rekoč jim: »Glejte, privedem ga k vam, da boste lahko spoznali, da ne najdem krivde na njem.«',
        5: 'Potem je prišel Jezus naprej, noseč trnovo krono in škrlatno svečano oblačilo. In Pilat jim reče: »Glejte, človek!«',
        6: 'Ko so ga torej visoki duhovniki in častniki zagledali, so zavpili, rekoč: »Križaj ga, križaj ga.« Pilat jim reče: »Vzemite ga in ga križajte, kajti jaz ne najdem krivde na njem.«',
        7: 'Judje so mu odgovorili: »Mi imamo postavo in po naši postavi bi moral umreti, ker se je delal Božjega Sina.«',
        8: 'Ko je torej Pilat slišal to besedo, se je še bolj zbal',
        9: 'in ponovno odšel v sodno dvorano in reče Jezusu: »Od kod si?« Toda Jezus mu ni dal odgovora.',
        10: 'Tedaj mu Pilat reče: »Meni ne odgovoriš? Ne veš, da imam oblast, da te križam in imam oblast, da te izpustim?«',
        11: 'Jezus je odgovoril: »Zoper mene sploh ne bi mogel imeti nobene oblasti, razen če ti ne bi bila dana od zgoraj. Zato ima večji greh tisti, ki me je izročil tebi.«',
        12: 'In odslej si je Pilat prizadeval, da ga izpusti. Toda Judje so zavpili, rekoč: »Če tega človeka izpustiš, nisi cesarjev prijatelj; kdorkoli sebe dela kralja, govori zoper cesarja.«',
        13: 'Ko je torej Pilat slišal to besedo, je privedel Jezusa naprej in sedel na sodni stol na kraju, ki se imenuje Tlak, toda v hebrejščini Gabatá.',
        14: 'Bila pa je priprava na pasho in okoli šeste ure; in Judom reče: »Glejte, vaš Kralj!«',
        15: 'Toda oni so zakričali: »Proč z njim, proč z njim, križaj ga.« Pilat jim reče: »Ali naj križam vašega Kralja?« Visoki duhovniki so odgovorili: »Nimamo kralja razen cesarja.«',
        16: 'Tedaj jim ga je torej izročil, da bi bil križan. In vzeli so Jezusa ter ga odvedli proč.',
        17: 'In ko je nesel svoj križ, je odšel naprej na kraj, imenovan kraj lobanje, ki se v hebrejščini imenuje Golgota,',
        18: 'kjer so ga križali in z njim dva druga, na vsaki strani enega in Jezusa v sredi.',
        19: 'In Pilat je napisal napis ter ga postavil na križ. In pisanje je bilo: JEZUS NAZAREČAN, JUDOVSKI KRALJ.',
        20: 'Ta napis so potem brali mnogi izmed Judov, kajti kraj, kjer je bil Jezus križan, je bil blizu mesta, in to je bilo napisano v hebrejščini in grščini ter latinščini.',
        21: 'Tedaj so visoki judovski duhovniki Pilatu rekli: »Ne napiši: ›Judovski Kralj,‹ temveč, da je on rekel: ›Jaz sem Kralj Judov.‹«',
        22: 'Pilat je odgovoril: »Kar sem napisal, sem napisal.«',
        23: 'Potem so vojaki, ko so Jezusa križali, vzeli njegove obleke in naredili štiri dele, za vsakega vojaka del in prav tako njegov plašč. Torej plašč [pa] je bil brez šiva, ves spleten od vrha.',
        24: 'Med seboj so torej govorili: »Ne razparajmo ga, temveč mečimo žrebe zanj, čigav bo,« da bi se lahko izpolnilo pismo, ki pravi: ›Moja oblačila so si razdelili med seboj in za mojo suknjo so metali žrebe.‹ Te stvari so torej storili vojaki.',
        25: 'Torej tam, ob Jezusovem križu, so stale njegova mati in sestra njegove matere, Klopájeva žena Marija in Marija Magdalena.',
        26: 'Ko je torej Jezus videl svojo mater in učenca, ki je stal poleg, ki ga je ljubil, reče svoji materi: »Ženska, glej tvoj sin!«',
        27: 'Potem reče učencu: »Glej, tvoja mati!« In od te ure jo je ta učenec vzel v svoj lastni dom.',
        28: 'Po tem, ker je Jezus vedel, da so bile vse stvari sedaj dovršene, da bi se lahko izpolnilo pismo, reče: »Žejen sem.«',
        29: 'Torej, tam je bila postavljena posoda, polna kisa; in gobo so napolnili s kisom in jo nataknili na izop ter jo pristavili k njegovim ustom.',
        30: 'Ko je torej Jezus prejel kis, je rekel: »Dovršeno je« in nagnil svojo glavo ter izročil duha.',
        31: 'Judje so torej zato, ker je bila priprava, da na šabatni dan telesa ne bi ostala na križu (kajti ta šabatni dan je bil na prazničen dan), prosili Pilata, da bi bile lahko njihove noge zlomljene in da bi bili lahko odstranjeni.',
        32: 'Potem so prišli vojaki in zlomili noge prvega in drugega, ki sta bila križana z njim.',
        33: 'Toda ko so prišli k Jezusu in videli, da je bil že mrtev, njegovih nog niso zlomili,',
        34: 'toda eden izmed vojakov je s sulico prebodel njegovo stran in nemudoma sta od tam pritekli kri in voda.',
        35: 'In tisti, ki je to videl, je izjavil in njegova izjava je resnična; in on ve, da govori resnico, da bi vi lahko verovali.',
        36: 'Kajti te stvari so bile storjene, da bi bilo izpolnjeno pismo: ›Nobena njegova kost ne bo zlomljena.‹',
        37: 'In ponovno drugo pismo pravi: ›Gledali bodo nanj, ki so ga prebodli.‹',
        38: 'In po tem je Jožef iz Arimateje, ki je bil Jezusov učenec, toda zaradi strahu pred Judi skrivaj, prosil Pilata, da bi lahko odnesel Jezusovo telo; in Pilat mu je dal dovoljenje. Prišel je torej in vzel Jezusovo telo.',
        39: 'In prav tako je prišel Nikodém, ki je najprej ponoči prišel k Jezusu in prinesel mešanico mire in aloje, težko okoli sto funtov.',
        40: 'Potem sta snela Jezusovo telo in ga z dišavami ovila v lanene trakove, kakršen je judovski običaj pokopa.',
        41: 'Torej na kraju, kjer je bil križan, je bil vrt in na vrtu nov mavzolej, v katerega človek še nikoli ni bil položen.',
        42: 'Zaradi judovskega dneva priprave sta torej Jezusa položila tja, kajti mavzolej je bil blizu.',
    },
    20: {
        1: 'Prvi dan tedna pride Marija Magdalena zgodaj, ko je bilo še temno, k mavzoleju in vidi kamen odvzet stran od mavzoleja.',
        2: 'Tedaj steče in pride k Simonu Petru in k drugemu učencu, ki ga je imel Jezus rad in jima reče: »Gospoda so odnesli iz mavzoleja in ne vemo, kam so ga položili.«',
        3: 'Peter in ta drugi učenec sta torej odšla naprej in prišla k mavzoleju.',
        4: 'Tako sta oba skupaj tekla; drugi učenec pa je Petra prehitel in prvi prišel k mavzoleju.',
        5: 'In ko se je sklonil navzdol in pogledal noter, je videl ležati lanene trakove, vendar ni vstopil vanj.',
        6: 'Tedaj pride Simon Peter, ki mu je sledil in gre v mavzolej ter vidi ležati lanene trakove;',
        7: 'prtič pa, ki je bil okoli njegove glave, ni ležal z lanenimi trakovi, temveč je bil sam zase skupaj zvit na kraju.',
        8: 'Tedaj je vstopil tudi ta drugi učenec, ki je prvi prišel k mavzoleju in videl je in veroval.',
        9: 'Kajti doslej še nista poznala pisma, da mora vstati od mrtvih.',
        10: 'Potem sta učenca ponovno odšla na njun lastni dom.',
        11: 'Toda Marija je jokajoč stala zunaj mavzoleja in med jokom se je sklonila navzdol ter pogledala v mavzolej',
        12: 'in vidi sedeti dva angela v belem, enega pri glavi, drugega pa pri stopalih, kjer je ležalo Jezusovo telo.',
        13: 'In onadva sta ji rekla: »Ženska, zakaj jokaš?« Reče jima: »Ker so odnesli mojega Gospoda, pa ne vem, kam so ga položili.«',
        14: 'In ko je to rekla, se je obrnila nazaj ter zagledala Jezusa, kako stoji, pa ni vedela, da je bil to Jezus.',
        15: 'Jezus ji reče: »Ženska, zakaj jokaš? Koga iščeš?« Ker je mislila, da je vrtnar, mu reče: »Gospod, če si ga odnesel od tod, mi povej, kam si ga položil in odnesla ga bom proč.«',
        16: 'Jezus ji reče: »Marija.« Obrnila se je in mu reče: »Rabuni,« kar pomeni: »Učitelj.«',
        17: 'Jezus ji reče: »Ne dotakni se me, kajti nisem se še dvignil k svojemu Očetu, toda pojdi k mojim bratom in jim povej: ›Dvignem se k svojemu Očetu in vašemu Očetu in k svojemu Bogu in vašemu Bogu.‹«',
        18: 'Marija Magdalena je prišla ter učencem povedala, da je videla Gospoda in da ji je govoril te stvari.',
        19: 'Potem je istega dne zvečer, ko je bil prvi dan tedna, ko so bila vrata, kjer so bili učenci zbrani, zaradi strahu pred Judi zaprta, prišel Jezus ter stopil na sredo in jim reče: »Mir vam bodi.«',
        20: 'In ko je tako rekel, jim je pokazal svoji roki in svojo stran. Potem ko so videli Gospoda, so bili učenci veseli.',
        21: 'Tedaj jim je Jezus ponovno rekel: »Mir vam bodi. Kakor me je moj Oče poslal, točno tako jaz vas pošiljam.«',
        22: 'In ko je to rekel, je dihnil nanje in jim reče: »Prejmite Svetega Duha.',
        23: 'Katerimkoli grehe odpustite, so jim odpuščeni; in katerimkoli grehe zadržite, so jim zadržani.«',
        24: 'Toda ko je prišel Jezus, Tomaža, enega izmed dvanajsterih, ki se je imenoval Dvojček, ni bilo z njimi.',
        25: 'Drugi učenci so mu torej rekli: »Videli smo Gospoda.« On pa jim je rekel: »Razen če ne bom videl na njegovih rokah odtisa žebljev in svojega prsta položil v odtis žebljev in svoje roke porinil v njegovo stran, ne bom veroval.«',
        26: 'In po osmih dneh so bili njegovi učenci ponovno znotraj in Tomaž z njimi. Potem je pri zaprtih vratih prišel Jezus in stal na sredi ter rekel: »Mir vam bodi.«',
        27: 'Potem reče Tomažu: »Sezi s svojim prstom sèm in poglej moji roki in sezi s svojo roko tja ter jo porini v mojo stran in ne bodi neveren, temveč veren.«',
        28: 'In Tomaž je odgovoril ter mu rekel: »Moj Gospod in moj Bog.«',
        29: 'Jezus mu reče: »Tomaž, ker si me videl, si veroval; blagoslovljeni so tisti, ki niso videli, pa so vendarle verovali.«',
        30: 'In resnično je v prisotnosti svojih učencev Jezus storil mnoga druga znamenja, ki niso zapisana v tej knjigi,',
        31: 'toda ta so zapisana, da bi vi lahko verovali, da Jezus je Kristus, Božji Sin in da bi verujoč, lahko imeli življenje v njegovem imenu.',
    },
    21: {
        1: 'Po teh stvareh je Jezus sebe učencem ponovno prikazal pri Tiberijskem morju in sebe je prikazal na ta način.',
        2: 'Tam so bili skupaj Simon Peter in Tomaž, imenovan Dvojček in Natánael iz galilejske Kane in Zebedejeva sinova ter dva druga izmed njegovih učencev.',
        3: 'Simon Peter jim reče: »Grem na ribolov.« Dejali so mu: »Tudi mi gremo s teboj.« Odšli so in takoj vstopili na ladjo, pa tisto noč niso ničesar ujeli.',
        4: 'Toda sedaj, ko je torej prišlo jutro, je na obali stal Jezus, toda učenci niso vedeli, da je bil Jezus.',
        5: 'Potem jim Jezus reče: »Otroci, imate kaj hrane?« Odgovorili so mu: »Ne.«',
        6: 'In rekel jim je: »Vrzite mrežo na desno stran ladje in boste našli.« Zato so jo vrgli, pa je torej niso mogli izvleči zaradi množice rib.',
        7: 'Ta učenec, ki ga je Jezus ljubil, reče torej Petru: »Gospod je.« Takoj ko je Simon Peter slišal, da je bil to Gospod, si je k sebi opasal svoj ribiški plašč (kajti bil je nag) in se vrgel v morje.',
        8: 'Ostali učenci pa so prišli na majhni ladji; (kajti niso bili daleč od kopnega, temveč kot bi bilo dvesto komolcev) ter vlekli mrežo z ribami.',
        9: 'Takoj ko so prišli h kopnini, so tam zagledali žerjavico in na njej položeno ribo ter kruh.',
        10: 'Jezus jim reče: »Prinesite od rib, ki ste jih pravkar ujeli.«',
        11: 'Simon Peter se je povzpel in potegnil mrežo, polno velikih rib, sto triinpetdeset, na kopno; in četudi jih je bilo vseh tako mnogo, se mreža vendarle ni strgala.',
        12: 'Jezus jim reče: »Pridite in obedujte.« Nihče izmed učencev pa si ga ni drznil vprašati: »Kdo si?« ker so vedeli, da je bil Gospod.',
        13: 'Jezus potem pride in vzame kruh in jim ga daje ter prav tako ribo.',
        14: 'To je sedaj tretjič, da se je Jezus prikazal svojim učencem, potem ko je bil obujen od mrtvih.',
        15: 'Torej ko so obedovali, reče Jezus Simonu Petru: »Simon, Jonov sin, me ljubiš bolj kakor tile?« On mu reče: »Da Gospod, ti veš, da te imam rad.« Rekel mu je: »Hrani moja jagnjeta.«',
        16: 'Ponovno mu drugič reče: »Simon, Jonov sin, me ljubiš?« Rekel mu je: »Da Gospod, ti veš, da te imam rad.« Rekel mu je: »Pasi moje ovce.«',
        17: 'Reče mu tretjič: »Simon, Jonov sin, me imaš rad?« Peter je bil užaloščen, ker mu je tretjič rekel: »Ali me imaš rad?« In rekel mu je: »Gospod, ti veš vse stvari; ti veš, da te imam rad.« Jezus mu reče: »Hrani moje ovce.',
        18: 'Resnično, resnično, povem ti: ›Ko si bil mlad, si se opasoval in hodil, kamor si hotel, toda ko boš star, boš iztegnil svoji roki in drug te bo opasal in te vodil, kamor nočeš.‹«',
        19: 'To je govoril in s tem naznanil s kakšno smrtjo naj bi proslavil Boga. In ko je to povedal, mu reče: »Sledi mi.«',
        20: 'Potem je Peter, ko se je obrnil okoli, videl slediti učenca, ki ga je Jezus ljubil, ki je prav tako pri večerji slonel na njegovih prsih in rekel: »Gospod, kdo je tisti, ki te izdaja?«',
        21: 'Medtem ko ga je Peter gledal, reče Jezusu: »Gospod in kaj bo ta človek storil?«',
        22: 'Jezus mu reče: »Če hočem, da ostane, dokler ne pridem, kaj ti je to mar? Ti hodi za menoj.«',
        23: 'Potem je šla ta beseda naokoli med brati, da naj ta učenec ne bi umrl, čeprav mu Jezus ni rekel: »Ne bo umrl,« temveč: »Če jaz hočem, da ostane, dokler ne pridem, kaj ti je to mar?«',
        24: 'To je učenec, ki pričuje o teh stvareh in je napisal te stvari in mi vemo, da je njegovo pričevanje resnično.',
        25: 'In obstaja tudi mnogo drugih stvari, ki jih je Jezus storil, katere, če bi jih vse zapisali, mislim, da celó sam svet ne bi mogel vsebovati knjig, ki bi bile napisane. Amen.',
    },
}
